(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-layoutlite-token-level-implicit-layo-2026"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-1\">一 · 从一次真实的发票洪峰说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-2\">二 · 显式版面分析的三个硬代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-3\">三 · 批调度视角：为什么旧方案在服务端非改不可</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-4\">四 · 旧方案的失败不是精度问题，是结构问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-5\">五 · 一个可对照的请求轨迹</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-6\">六 · 失效边界：显式版面分析的串行税与回退代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-7\">七 · 请求形态：以“页”为原子，以“视觉 token”为通货</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-8\">八 · 并发与批大小：预算对齐而非请求对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-9\">九 · SLO：首 token 延迟与整页时延是两个不同的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-10\">十 · 长尾：版面复杂度是隐藏的请求特征</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-11\">十一 · 负载塑造方案，方案反过来限制负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-12\">十二 · 负载形态如何反向约束 token 级版面方案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-13\">十三 · 视觉编码器主循环：从 FP16 到 NVFP4 的精度阶梯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-14\">十四 · 版面头的数值敏感性：小算力、高精度需求</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-15\">十五 · 累加精度与误差传播：谁在放大误差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-16\">十六 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 的推理含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-17\">十七 · 量化方案与回退路径的联合校准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-18\">十八 · 显存账本的三个账户与可复算预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-19\">十九 · 分页：把 KV 从连续块变成可拼装的页</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-20\">二十 · 压缩与复用：视觉 token 是唯一可压的变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-21\">二十一 · 卸载：把冷页赶出 HBM，把热页钉住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-22\">二十二 · 带宽瓶颈在哪：HBM3e 的读放大与有效带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-23\">二十三 · 容量规划：从 SLO 反推页预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-24\">二十四 · 连续批处理：以 token 预算而非请求数为组批单位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-25\">二十五 · Chunked prefill：把视觉编码与解码切开做时间片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-26\">二十六 · 优先级与抢占：按版面头置信度分流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-27\">二十七 · 分离式预填/解码：把视觉编码与自回归拆到不同卡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-28\">二十八 · 尾延迟怎么压：三个可操作的杠杆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-29\">二十九 · 批调度边界：压缩比、回退率与尾延迟的三方拉扯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-30\">三十 · 从“单卡单页”到“多卡多页”：LayoutLite 的切分对象是什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-31\">三十一 · NVLink 5 与 NVSwitch：机柜内域与域间边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-32\">三十二 · 通信何时成为瓶颈：三个可观测判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-33\">三十三 · NIXL 传输与分离式部署：视觉段与解码段的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-34\">三十四 · 切分决策与回退路径的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-35\">三十五 · 并行切分的边界：当通信取代版面检测成为瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-36\">三十六 · 精度塌陷：从版面头置信度到注意力偏置的失效链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-37\">三十七 · OOM 与显存峰值：回退路径是隐藏的放大器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-38\">三十八 · 批抖动与尾延迟：序列长度方差是根因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-39\">三十九 · 静默降级：不报错但输出变差的三种形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-40\">四十 · 监控面与回滚：把回退率当作一等 SLO 信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-41\">四十一 · 失败模式与诊断：从回退率到批内方差的观测闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-42\">四十二 · 口径先于数字：这份材料能报什么、不能报什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-43\">四十三 · 硬件档位与 batch 口径：组批单位不是请求数而是 token 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-44\">四十四 · 指标成对报告：TTFT 与 TPOT 不能各自单独出现</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-45\">四十五 · 哪些提升不可比：四类典型错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-46\">四十六 · 自己动手的测量清单：从机制量推到端到端</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-47\">四十七 · 口径边界：回退率、网格粒度与不可比的“提速”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-48\">四十八 · 迁移到非文档视觉模型：改的是注入位置，不是压缩模块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-49\">四十九 · 迁到非 OCR 任务：解码器侧假设最先失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-50\">五十 · 规模上限：网格粒度与回退率共同封顶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-51\">五十一 · 数值精度迁移：NVFP4/FP8 下先校准偏置，再校准压缩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-52\">五十二 · 不适用边界：三类场景应直接放弃迁移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-layoutlite-token-level-implicit-layo-2026-sec-53\">五十三 · 迁移与边界：换模型、换领域、上规模时真正要动的地方</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:572px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 572.4 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">整页文档图像经预处理归一化后送入视觉编码器，一次前向得到网格化视觉 t…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">token 级版面头在序列维度预测版面角色与阅读顺序偏置，生成注意力掩…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">视觉 token 压缩与合并模块按相似度合并冗余 token，缩短送入…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">跨模态解码器以自回归方式生成文本，跨模态注意力读取压缩后的全页视觉 t…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">KV cache 保存压缩视觉 token 与已生成文本历史，批调度按…</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出后处理按隐式顺序信号拼接文本，失败样本回退到显式版面分析路径。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-1\">一 · 从一次真实的发票洪峰说起</h3>\n<p>设想一家做财税 SaaS 的团队，在申报季最后三天迎来文档 OCR 请求的尖峰：每小时数万页，混合着增值税发票、银行流水、多栏合同与带公式的报表。请求从网关进来时只有一个 deadline——首 token 延迟必须压在几百毫秒量级，整页文本要在秒级内返回，否则前端的上传进度条就会卡死。工程团队打开 profiler，看到的不是解码器慢，而是时间线被切成了几段互不相干的前向：先跑一个版面检测模型（通常是 DETR 系或分割系），把页面切成标题、段落、表格、公式若干区域；再按检测框逐块裁剪、缩放、补齐；然后每个区域单独送进识别模型做一次视觉编码；最后用一套阅读顺序规则把各区域的文本拼回去。这条流水线上，检测模型的前向是串行的前置闸门，它的延迟直接叠加在每一个请求的端到端时延上，而它的输出又是一组离散的框，框与框之间的排序逻辑写在 CPU 侧的启发式代码里。</p>\n<p>这个场景的关键不是“检测模型不够快”，而是整条链路的结构性代价：视觉编码被重复执行。整页图像先被检测模型编码一遍，随后每个裁剪块又被识别模型各自编码一遍，同一片像素在不同分辨率、不同上下文下被反复送进 GPU。对于一页含二三十个区域的合同，识别阶段的视觉编码次数与区域数成正比，而每次编码都要占用显存带宽与算力，批调度器还得为长短不一的裁剪块做 padding，批内序列长度方差极大。这就是 LayoutLite 要动的现场：版面分析作为像素级检测模块存在，使 OCR 推理退化为“检测—裁剪—再编码—排序”的级联流水线。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-2\">二 · 显式版面分析的三个硬代价</h3>\n<p>把旧方案拆开看，代价集中在三处，且互相放大。第一是串行延迟：检测前向必须完整结束，裁剪坐标才能确定，识别阶段才能启动，两段之间没有重叠机会；在连续批处理（continuous batching）的调度器里，这意味着一个请求的 KV 与算力占用被拉长成两段不连续的窗口，调度器难以把检测阶段的空隙填给别的请求。第二是重复视觉编码：整页编码与区域编码是两次独立的视觉前向，区域编码丢失了跨区域的全局上下文，却又付出了与整页编码同量级的像素吞吐。第三是框误差传播：检测框偏一点，裁剪就把表格的一列切掉半行，识别模型再强也补不回来；多栏与公式混排时，框的召回与排序规则共同决定阅读顺序，任何一处误判都会让输出文本的语义断裂。</p>\n<p>用系统量表达，旧链路的单请求时延可写成串行和：</p>\n<div class=\"formula\">$$T_{\\text{cascade}} = T_{\\text{det}} + T_{\\text{crop}} + \\sum_{i=1}^{N} T_{\\text{enc}}(r_i) + T_{\\text{dec}}(N)$$</div>\n<p>其中 N 是检测出的区域数，$T_{\\text{enc}}(r_i)$ 是第 i 个裁剪块的视觉编码时间。这个式子暴露了两件事：端到端时延随区域数线性增长，且 $T_{\\text{det}}$ 是无法与解码重叠的纯前置开销。显存侧同样难看——每个裁剪块在识别阶段都要保留自己的视觉 token 与 KV，批内 N 个块意味着 N 份视觉 KV 常驻，加上检测模型自身的权重与激活，显存峰值被两个模型同时抬高。吞吐侧则受批对齐拖累：不同页面的区域数从个位数到几十不等，padding 浪费的算力在混合负载下不可忽视。</p>\n<p>具体到一个多栏学术 PDF：检测器给出左栏三段、右栏两段、中间一个跨栏公式、底部一张表。裁剪后七个块被独立编码，公式块因为长宽比异常被缩放得模糊，表格块被切成两半，阅读顺序规则按“先左后右、先上后下”拼接，结果公式插进了右栏第二段中间。这个错误不是识别模型的错，而是像素级检测加启发式排序在结构复杂页面上的固有失配。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-3\">三 · 批调度视角：为什么旧方案在服务端非改不可</h3>\n<p>单请求的代价在并发下会被调度器放大。显式检测阶段是一个“全有或全无”的同步点：一个 batch 里所有请求都得等各自的检测前向完成，才能进入识别阶段，而检测模型的输入是整页高分辨率图像，其显存占用与批内页数成正比。调度器为了不让 GPU 空转，往往把检测与识别放在不同流或不同卡上，于是又引入跨卡传输与同步开销。更麻烦的是批内方差：一页简单收据只有一个区域，一页复杂报表有四十个区域，识别阶段的序列长度相差一个数量级，连续批处理被迫按最长序列分配 KV 预算，短请求的显存被浪费，长请求则频繁触发重排。</p>\n<p>旧方案的吞吐上限可以用一个粗略的容量关系刻画：若单页平均区域数为 $\\bar{N}$，识别阶段每块的视觉 token 数为 $S_v$，则单页视觉 KV 占用正比于 $\\bar{N}\\cdot S_v$；而整页单次编码方案只需一份 $S_v'$（压缩后的整页 token 数）。当 $\\bar{N}$ 较大时，前者是后者的数倍，直接压缩了单卡可并发的页数。这就是为什么服务端团队在峰值流量下会看到 GPU 显存先于算力成为瓶颈——不是解码算不动，而是视觉 KV 装不下更多并发页。</p>\n<p>还有一个隐蔽代价：检测模型的输出是离散框，框的坐标要回到 CPU 做裁剪、缩放、排序，再组 batch 送回 GPU。这条 CPU-GPU 往返在低延迟 SLO 下是实打实的尾延迟来源，尤其当页面触发布局规则的复杂分支时。工程上常见的“检测批”和“识别批”分离部署，本质是用更多的卡与更复杂的队列来掩盖这条串行链，而不是消除它。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-4\">四 · 旧方案的失败不是精度问题，是结构问题</h3>\n<p>值得强调的是，显式版面分析在标准数据集上的检测指标并不差，问题在于它的输出形态与下游识别需求不匹配。检测框是像素空间的离散对象，而识别模型需要的是 token 序列上的连续上下文；两者之间的转换——裁剪、缩放、排序——全部由外挂逻辑承担，每一步都在引入不可微的误差与额外的系统开销。多栏文档的阅读顺序尤其脆弱：栏间关系、跨栏元素、脚注与正文的层级，很难用“先上后下、先左后右”的规则稳定恢复，规则越写越复杂，CPU 侧的排序逻辑本身成了维护负担。</p>\n<p>从推理栈的角度，这意味着版面分析被放在了错误的位置：它本应是视觉编码的一部分，却被迫作为一个独立模型、一个独立阶段、一份独立显存存在。LayoutLite 的切入点正是把这个阶段收回进单次前向——视觉编码器对整页做一次前向，输出网格化 token，版面角色与阅读顺序以 token 级信号的形式存在，通过注意力偏置注入跨模态解码器。这样，版面理解与文本识别共享同一次视觉编码，区域裁剪与二次编码被取消，阅读顺序不再由 CPU 规则拼接，而是由 token 序列上的顺序信号隐式给出。</p>\n<p>代价结构随之改变：端到端时延从“检测 + N 次区域编码 + 解码”收缩为“一次整页编码 + 自回归解码”，前置同步点消失，视觉 KV 只保留一份压缩后的整页 token。批调度按页数与视觉 token 预算组批，批内方差从“区域数方差”变为“整页 token 数方差”，对齐成本下降。当然，这条路径引入了新的失败模式：版面头置信度不足或顺序信号冲突时，样本需要回退到显式检测路径，回退率会直接体现在尾延迟与显存峰值上；隐式信号还受视觉 token 网格粒度限制，细粒度表格与公式混排可能超出 token 级表达力。这些是本卷后续要展开的工程监控项，此处只需记住：旧方案的非改不可，不是因为检测模型不够准，而是因为它的串行结构与重复编码在服务端峰值下同时挤压了延迟、显存与批调度自由度。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-5\">五 · 一个可对照的请求轨迹</h3>\n<p>把两条链路放在同一张时间轴上对照。旧链路：t0 整页图像进检测模型，t1 检测完成、框回 CPU，t2 裁剪与排序完成、组批，t3 起 N 个区域并行编码，t4 编码完成、解码开始，t5 输出拼接。新链路：t0 整页图像进视觉编码器，t1 编码完成、版面头给出 token 级角色与顺序偏置、压缩合并模块缩短序列，t2 解码器开始自回归生成，跨模态注意力在带版面偏置的分布上直接读取全页 token，t3 生成结束、按隐式顺序信号拼接。差别不在单步快慢，而在旧链路有两个不可重叠的同步点（检测完成、裁剪组批完成），新链路只有一个编码前向作为前置，之后全部是解码器的连续批处理窗口。</p>\n<p>对调度器而言，新链路让一个请求从到达起就进入统一的 token 预算体系：视觉 token 数与文本历史共同决定 KV 占用，压缩比决定单批可容纳页数，版面头置信度决定是否分流到回退路径。工程判断因此变得具体——部署前要校准的是压缩比例与量化精度对细粒度版面的影响、回退阈值对尾延迟的抬升、以及网格粒度对表格与公式的覆盖能力，而不是去优化一个独立检测模型的 mAP。这正是这篇论文把版面分析从像素级检测改为 token 级隐式建模所要换来的东西：不是更高的检测分数，而是一条可以在 Blackwell 上按 token 预算调度、按单次编码摊薄显存、按注意力偏置承载版面结构的推理链路。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-6\">六 · 失效边界：显式版面分析的串行税与回退代价</h3>\n<p>先看一个真实在线场景：某票据与合同混合的文档 OCR 服务，单页请求在高峰时段以千级 QPS 涌入，SLO 卡在首 token 延迟与整页生成时延两段。旧栈的链路是检测—裁剪—排序—识别：版面检测模型先对整页做一次前向，输出检测框，再按框裁剪出若干区域图块，逐块送入识别模型，最后按显式排序模块拼接文本。这条链路的系统代价不在单点算力，而在串行结构：检测前向必须等整页预处理完成，识别必须等全部框产出，排序必须等全部识别结束。设单页检测延迟为 <span class=\"inline-math\">T<sub>det</sub></span>、区域数为 <span class=\"inline-math\">N</span>、单区域识别延迟为 <span class=\"inline-math\">T<sub>rec</sub></span>，则端到端时延近似为</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}}\\approx T_{\\mathrm{det}}+N\\cdot T_{\\mathrm{rec}}+T_{\\mathrm{sort}}$$</div>\n<p>其中 <span class=\"inline-math\">N</span> 随版面复杂度增长，多栏、表格、公式混排文档的 <span class=\"inline-math\">N</span> 显著抬升，尾延迟被串行段直接放大。更隐蔽的代价是重复视觉编码：每个裁剪区域都要独立过一次视觉编码器，同一页的像素被反复编码，显存峰值随批内区域总数线性上升，批调度被迫按区域数而非页数对齐，吞吐被检测阶段拖住。</p>\n<p>框误差传播是第二个非改不可的理由。检测框的定位偏差会沿流水线放大：框偏移导致区域裁剪丢字或带入邻栏内容，识别模型在错误上下文里生成文本，排序模块再按框坐标恢复阅读顺序，一旦框重叠或漏检，顺序冲突无法在识别侧纠正。多栏文档中阅读顺序的稳定性依赖检测框的几何关系，表格与公式混排时框的层级嵌套使显式排序规则迅速膨胀，工程上只能靠启发式补丁维持，规则维护成本本身成为交付瓶颈。下表对比旧栈与新方案在关键系统维度上的结构差异：</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>显式检测旧栈</th><th>token 级隐式方案</th></tr></thead><tbody><tr><td>视觉编码次数</td><td>整页一次 + 每区域一次</td><td>整页一次</td></tr><tr><td>串行段</td><td>检测、逐区域识别、排序</td><td>编码、自回归解码</td></tr><tr><td>批对齐依据</td><td>区域数与框面积</td><td>页数与视觉 token 预算</td></tr><tr><td>KV cache 视觉部分</td><td>随区域数增长</td><td>随压缩后 token 数增长</td></tr></tbody></table>\n<p>但新方案并非无边界。隐式版面信号以注意力偏置形式注入跨模态注意力，其表达力受视觉 token 网格粒度约束：细粒度表格的单元格边界与公式的上下标关系可能落在同一网格 token 内，token 级角色分类无法区分，此时版面头置信度下降或输出顺序冲突，样本回退到显式版面分析路径。回退路径是这套方案的主要失败模式，它把串行检测重新引入链路，回退率直接决定尾延迟与显存峰值——高回退率下批调度会被串行段拖慢，压缩合并模块省下的 KV cache 又被回退样本的检测模型与区域裁剪抵消。工程判断是：部署时必须把版面头置信度分布、回退率、视觉 token 压缩比与批内序列长度方差列为一级监控项，按置信度分流组批，避免少数复杂版面样本污染整批的 SLO；压缩比例与量化精度需联合校准，压缩过度会削弱细粒度版面表达，而材料未给出量化方案与硬件档位数据，Blackwell 上的数值影响只能靠部署前自行校准，不能假设 NVFP4/FP8 对视觉编码器与跨模态注意力无代价。</p>\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-7\">七 · 请求形态：以“页”为原子，以“视觉 token”为通货</h3>\n<p>文档 OCR 推理的请求不是等长序列，而是一张整页图像。LayoutLite 把请求的计量单位从“像素框”改成“页 × 视觉 token 预算”：一次请求携带一页图像、一个由预处理决定的网格分辨率、以及压缩合并后实际送入解码器的视觉 token 数。可核查的测量口径必须同时记录三件事——原始页数、编码器输出的网格 token 数、压缩后的有效 token 数。三者之比就是压缩比，它直接决定单批能塞进多少页。若只记录页数而不记录压缩后 token 数，吞吐数字无法跨配置比较，因为同一页在不同网格粒度下占用的 KV cache 可以相差数倍。</p>\n<p>输入长度分布因此是双峰的：一端是单栏纯文本页，网格 token 大量冗余，压缩合并后序列很短；另一端是多栏表格与公式混排页，token 之间版面角色差异大、相似度合并受限，压缩比低、有效序列长。工程上应把这两端分开统计，分别给出 P50 与 P95 的有效 token 数，而不是给一个混合平均值。混合平均值会掩盖批内方差，而批内方差正是调度器最难处理的部分。</p>\n<div class=\"formula\">$$\\text{有效序列}=N_{\\text{grid}}\\cdot\\rho_{\\text{merge}},\\qquad \\text{单批页数}\\approx\\left\\lfloor \\frac{B_{\\text{tok}}}{N_{\\text{grid}}\\cdot\\rho_{\\text{merge}}}\\right\\rfloor$$</div>\n<p>其中 $B_{\\text{tok}}$ 是调度器为单批设定的视觉 token 预算，$\\rho_{\\text{merge}}$ 是压缩合并保留率。这个式子说明一个具体代价：压缩比每下降一档，单批页数线性下降，而解码阶段的 KV cache 占用线性上升。在 Blackwell 上，KV cache 的容量与带宽是硬约束，视觉部分的 token 数直接吃掉可用于文本历史的显存，因此 $\\rho_{\\text{merge}}$ 不是精度侧的锦上添花，而是容量规划的一等变量。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-8\">八 · 并发与批大小：预算对齐而非请求对齐</h3>\n<p>连续批处理在纯文本 LLM 上按 token 计费，在文档 OCR 上必须按“页 × 预算”对齐。LayoutLite 的调度单元是一页，但一页的解码步数由识别出的字符数决定，字符数又与版面密度相关。于是批内会出现“短页早退、长页拖尾”的经典长尾：一个表格页的解码步数远多于一个页眉页，先完成的请求释放出的 KV 槽位如果不能被新页立即复用，GPU 占用率就在尾部塌陷。</p>\n<p>可核查的口径是批内有效序列长度的方差与解码步数的方差，两者分开测。前者决定预填阶段的显存峰值，后者决定解码阶段的槽位周转。工程判断是：当版面头置信度分布出现明显低分簇时，不要把这些页混进高置信度批，而应按置信度分流成独立批——低置信度页有回退风险，一旦触发回退，该页会从 token 级并行路径切到显式检测路径，整批的节奏被打断。分流让回退的代价局部化，代价是牺牲一点批大小。</p>\n<ul>\n<li>测量项：批内页数、批内压缩后 token 总数、批内 token 数极差、批内解码步数极差。</li>\n<li>测量项：槽位复用间隔，即一页完成后到新页占位的解码步数。</li>\n<li>测量项：按版面头置信度分桶后的批占用率，用于判断分流阈值是否过严。</li>\n</ul>\n<p>一个具体例子：若某批混合了十页单栏文本与两页三线表，压缩合并对单栏页保留率低、对表格页保留率高，批内 token 极差被拉大，预填阶段按最大页分配显存，小页白占容量。把表格页单独成批后，两批各自的 token 极差收窄，显存峰值下降，代价是两次预填的固定开销。这个取舍在页数少时偏向混批，在页数多时偏向分流，分界点由预填固定开销与显存峰值的比值决定，需实测。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-9\">九 · SLO：首 token 延迟与整页时延是两个不同的约束</h3>\n<p>文档 OCR 的服务等级通常拆成两段：首 token 延迟对应“版面理解是否已经开始”，整页生成时延对应“这一页多久能交付”。LayoutLite 的链路把延迟集中在视觉编码与自回归解码两段，中间没有检测模块的串行等待，因此首 token 延迟主要由整页编码前向加第一次解码步构成，而整页时延由解码步数乘以每步时间加上编码时间构成。两段的优化手段不同：前者受编码器分辨率与网格粒度支配，后者受压缩比与批内并发支配。</p>\n<p>可核查口径必须声明测量边界：首 token 是从请求入队算起还是从预处理完成算起，整页时延是否包含后处理拼接与回退判定。回退判定发生在生成结束后，若置信度低于阈值，样本转入显式路径，此时整页时延被二次拉长，且显存峰值出现第二次抬升。因此 SLO 报表里必须单列回退率与回退样本的时延分位数，否则尾延迟会被平均值掩盖。材料未给出具体阈值，工程上应以回退样本的 P99 时延作为容量规划的上界，而不是用全体样本的均值。</p>\n<div class=\"formula\">$$T_{\\text{page}}=T_{\\text{enc}}(N_{\\text{grid}})+S\\cdot T_{\\text{step}}(B_{\\text{batch}})+T_{\\text{post}}+r\\cdot T_{\\text{fallback}}$$</div>\n<p>其中 $S$ 是解码步数，$r$ 是回退指示，$T_{\\text{fallback}}$ 是显式路径的额外开销。这个式子的工程含义是：回退率 $r$ 不需要很高就能主导尾延迟，因为 $T_{\\text{fallback}}$ 包含一次独立的检测前向与区域裁剪。控制尾延迟的最直接手段不是加快解码，而是把 $r$ 压下去——通过网格粒度与压缩比的校准，让版面头在细粒度表格页上也不掉到阈值以下。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-10\">十 · 长尾：版面复杂度是隐藏的请求特征</h3>\n<p>文档请求的长度分布不是随机的，它由版面复杂度分层。单栏连续文本、双栏学术页、三线表、公式混排、扫描倾斜页，各自的 token 级版面信号强度不同。隐式版面分析在 token 网格上表达阅读顺序，网格越粗，细粒度表格的行列关系越容易被合并掉，版面头置信度下降，回退概率上升。这就是长尾的机制来源：不是请求到达率的长尾，而是版面表达力的长尾。</p>\n<p>可核查的测量口径是把页面按版面类型打标，分别统计每类的压缩保留率、版面头置信度均值、回退率与整页时延 P95。四张表放在一起看，才能判断瓶颈在编码分辨率还是在压缩策略。若某类页面的置信度均值正常但回退率高，说明阈值设置与置信度分布不匹配；若置信度均值本身就低，说明网格粒度不足，需要提高编码分辨率，代价是 $N_{\\text{grid}}$ 上升、单批页数下降、预填显存上升。这是一个明确的精度与吞吐对冲，不能用“调参”含糊过去。</p>\n<table class=\"mini\"><thead><tr><th>版面类型</th><th>压缩保留率</th><th>版面头置信度</th><th>回退率</th><th>整页时延 P95</th></tr></thead><tbody><tr><td>单栏文本</td><td>低</td><td>高</td><td>低</td><td>受解码步数支配</td></tr><tr><td>双栏学术</td><td>中</td><td>中高</td><td>低</td><td>受顺序信号冲突支配</td></tr><tr><td>三线表</td><td>高</td><td>中</td><td>中</td><td>受压缩比与回退支配</td></tr><tr><td>公式混排</td><td>高</td><td>低</td><td>高</td><td>受回退路径支配</td></tr></tbody></table>\n<p>表中数值列为定性档位，材料未给出可核验数字，部署时应以自测填充。表格的用途是强制把“长尾”拆成可归因的列，而不是笼统地说某类文档慢。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-11\">十一 · 负载塑造方案，方案反过来限制负载</h3>\n<p>负载形态不是被动输入，它被方案反向塑造。LayoutLite 取消检测框后，前端不再需要按框裁剪，预处理从“检测—裁剪—排序”退化为“整页归一化”，这降低了单请求的前处理开销，但也把分辨率决策权集中到网格配置上。服务方一旦固定网格粒度与压缩比，就等于固定了可接受的版面复杂度上限：超出该上限的页面会以回退或精度损失的形式表现出来。于是容量规划不只是算 GPU 数，而是先定“服务承诺覆盖哪些版面类型”，再反推网格与压缩配置。</p>\n<p>另一个反向约束来自批调度：按 token 预算组批意味着调度器必须知道每页压缩后的 token 数，而这个数在编码完成前不可知。可行的做法是用页面元数据（尺寸、预估版面密度）做预分组，编码后再做批内微调；不可行的做法是等编码完再组批，那会让预填阶段空转。这里的代价是调度器需要维护一个预估模型，预估偏差直接转化为批内方差。工程判断是：预估模型宁可保守（高估 token 数），因为高估只浪费容量，低估会导致批超预算、显存峰值越界。</p>\n<ul>\n<li>机制：预分组按页面尺寸与版面密度分桶，编码后按实际压缩 token 数重排。</li>\n<li>代价：预分组误差抬升批内方差，方差抬升预填显存峰值。</li>\n<li>例子：扫描倾斜页因预估密度偏低被分入小 token 桶，编码后实际 token 数偏高，触发批重排，重排本身消耗调度周期。</li>\n</ul>\n<p>最后落在监控项上：版面头置信度分布、回退率、压缩保留率、批内 token 方差、槽位复用间隔，这五项构成负载与方案互相塑造的可观测闭环。缺任何一项，容量规划就只能靠端到端均值，而均值在长尾面前没有决策价值。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-12\">十二 · 负载形态如何反向约束 token 级版面方案</h3>\n<p>LayoutLite 的批调度以“页数 × 视觉 token 预算”为对齐口径：压缩合并后的序列长度决定单批可容纳页数，而版面复杂度差异会直接抬高批内序列长度方差。设单页压缩后视觉 token 数为 <span class=\"inline-math\">n<sub>i</sub></span>、批预算为 <span class=\"inline-math\">B</span>，则可容纳页数 <span class=\"inline-math\">k = max{k : Σ<sub>i=1..k</sub> n<sub>i</sub> ≤ B}</span>；当批内混入细粒度表格或公式混排页时，<span class=\"inline-math\">n<sub>i</sub></span> 偏大，批被少数长页占满，短页只能另起一批，吞吐被序列长度方差而非平均长度支配。可核查口径应记录：每页压缩前后 token 数、批内 <span class=\"inline-math\">n<sub>i</sub></span> 的方差、单批实际页数、视觉编码段与自回归解码段各自的耗时占比，以及 KV cache 中视觉部分与文本历史的字节数。这些量在部署侧可直接采集，不依赖论文数值。</p>\n<p>负载反过来也限制方案边界。版面头置信度低于阈值或输出顺序冲突时样本回退到显式版面分析路径，回退率直接决定尾延迟与显存峰值：回退样本要额外跑检测模型与区域裁剪，等于在单次编码链路上插入一段串行前置模块，高回退率下批调度会被这段串行检测拖慢，原本“一次整页前向”的延迟优势被抵消。因此 SLO 不能只看首 token 延迟与整页生成时延的均值，必须把回退样本的单页时延单独统计并计入 P99；监控项应包含版面头置信度分布、回退率、视觉 token 压缩比与批内序列长度方差，四者共同刻画负载是否落在方案的有效区间内。</p>\n<p>失效条件集中在两处。其一是网格粒度：隐式版面信号受视觉 token 网格限制，细粒度表格与公式混排可能超出 token 级表达力，此时压缩合并若按相似度过度合并，会进一步削弱版面表达并影响 OCR 精度，压缩比例必须与量化精度联合校准，而材料未给出量化方案与硬件档位，NVFP4/FP8 对视觉编码器与跨模态注意力的数值影响需部署前自行校准。其二是误用：把 token 级版面信号当作显式检测框使用，会丢失其并行注入的延迟优势并引入额外后处理。工程判断是：按版面头置信度分流请求，高置信样本走隐式路径、低置信样本预置到显式路径的独立队列，避免回退拖累整批；同时以压缩后 token 预算而非页数作为组批主键，把序列长度方差压到可控范围。</p>\n<table class=\"mini\"><thead><tr><th>观测项</th><th>测量口径</th><th>约束对象</th></tr></thead><tbody><tr><td>压缩比</td><td>压缩前/后视觉 token 数</td><td>KV cache 视觉占用</td></tr><tr><td>批内长度方差</td><td>批内各页 n<sub>i</sub> 的离散度</td><td>单批页数与吞吐</td></tr><tr><td>回退率</td><td>回退样本数 / 总样本数</td><td>P99 尾延迟与显存峰值</td></tr></tbody></table>\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-13\">十三 · 视觉编码器主循环：从 FP16 到 NVFP4 的精度阶梯</h3>\n<p>LayoutLite 的推理链路里，视觉编码器承担整页图像的单次前向，是唯一必须处理稠密像素网格的阶段，也是数值精度选择最敏感的地方。工程上通常从 FP16/BF16 起步：BF16 与 FP16 同为 16 位，但 BF16 保留 8 位指数、仅 7 位尾数，动态范围与 FP32 同级，适合视觉主干中激活分布跨度大的层（如 LayerNorm 之后的残差累加）；FP16 有 10 位尾数，精度更高但动态范围窄，遇到大幅值激活容易溢出。选择哪一种，取决于视觉编码器是否在训练期就用了对应精度，推理期切换会引入分布偏移。</p>\n<p>再往下一档是 FP8。Blackwell 的第五代 Tensor Core 对 FP8 的 E4M3 与 E5M2 两种格式都有原生支持：E4M3 尾数多、适合权重与激活，E5M2 范围大、适合梯度类或动态范围不可控的张量。FP8 的关键不在格式本身，而在缩放因子（scale）的粒度——per-tensor 缩放实现简单但误差大，per-channel 或 per-block（如 128×128 分块）缩放能把量化误差压到可接受区间。视觉编码器的卷积与注意力投影层对 per-channel 权重缩放友好，激活侧则更依赖 per-token 动态缩放。</p>\n<p>最激进的是 NVFP4：4 位尾数加块级缩放，Blackwell 的 Tensor Core 对其有专门的数据通路。NVFP4 的表示能力有限，放在视觉编码器主干上会明显削弱细粒度纹理与字符笔画的区分度，而 LayoutLite 的版面角色预测恰恰依赖 token 级视觉特征的细微差异。因此合理的分工是：视觉编码器主干保持 FP8 或 BF16，把 NVFP4 留给跨模态解码器的权重与 KV cache——解码器以自回归方式生成文本，对视觉细节的依赖通过注意力读取已编码的 token 特征，而非重新感知像素。</p>\n<p>代价侧要算清楚：视觉编码器单次前向的算力开销与整页像素数成正比，精度每降一档，Tensor Core 的有效吞吐提升，但量化/反量化与缩放因子的读写会占用显存带宽。以整页文档图像为例，若视觉主干从 BF16 切到 FP8，权重显存减半、矩阵乘吞吐提升，但每层激活的动态缩放引入额外的一次归约与一次乘加，在 batch 较小时这部分开销可能吃掉吞吐收益。工程判断是：批内页数足够大、视觉编码算力成为瓶颈时才值得下探到 FP8；页数少、延迟由单页前向主导时，BF16 的稳定性和免校准更划算。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-14\">十四 · 版面头的数值敏感性：小算力、高精度需求</h3>\n<p>token 级版面头在序列维度上预测版面角色与阅读顺序偏置，输出的是分类 logits 与顺序偏置，参数量远小于视觉主干，但它对数值误差的敏感度反而更高。原因在于版面角色是离散类别，logits 之间的边际差距可能很小——多栏文档中相邻 token 属于“正文”还是“标题”的判别，往往取决于特征中很细微的差异。低精度量化会把这种边际差距抹平，导致版面角色误判，进而让注意力偏置注入错误的位置，阅读顺序在解码时被隐式打乱。</p>\n<p>因此版面头应保持较高精度：权重可用 FP8 但需 per-channel 缩放，logits 计算与 softmax 前的累加建议保持 FP16 或 BF16 累加，避免 FP8 累加器在类别数较多时丢精度。顺序偏置作为注意力掩码或位置偏置注入，其数值范围通常较小，量化到 FP8 的 E4M3 时要注意偏置的符号与量级——偏置被截断会让某些 token 的注意力权重被系统性压低，表现为整段文本漏识别。</p>\n<div class=\"formula\">$$\\mathrm{Attn}(q,k)=\\mathrm{softmax}\\left(\\frac{qk^{\\top}}{\\sqrt{d}}+b^{\\mathrm{layout}}\\right)$$</div>\n<p>逐项解释：$qk^{\\top}$ 是查询与键的内积，$\\sqrt{d}$ 是维度缩放因子，防止内积随维度增长而过大导致 softmax 饱和；$b^{\\mathrm{layout}}$ 是版面头输出的顺序偏置，按 token 对注入，正值提升该 token 被注意的概率、负值压低。工程上这个式子的代价在于：$b^{\\mathrm{layout}}$ 是逐 token 对的稠密偏置，序列长度为 $n$ 时偏置矩阵是 $n\\times n$，显存占用随压缩后的视觉 token 数平方增长。视觉 token 压缩与合并模块把 $n$ 降下来，直接减轻的就是这块偏置矩阵与注意力分数的显存与带宽压力。若把 $b^{\\mathrm{layout}}$ 量化到 FP8，偏置矩阵显存再减半，但 softmax 前的加法必须在 FP16/BF16 累加器里做，否则偏置与内积的量级差异会被量化噪声淹没。</p>\n<p>具体例子：一页双栏学术论文，左栏末尾的 token 与右栏开头的 token 在网格上相邻但阅读顺序相隔一整栏。版面头给这对 token 注入负偏置，解码器在生成左栏最后一行时不会把注意力泄漏到右栏开头。若偏置被 FP8 量化截断到零，解码器可能提前跳到右栏，输出顺序错乱——这类错误不会体现在单 token 的识别精度上，却直接破坏整页文本的可用性。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-15\">十五 · 累加精度与误差传播：谁在放大误差</h3>\n<p>Blackwell 的 Tensor Core 在 FP8 与 NVFP4 模式下，矩阵乘的乘加运算在硬件内完成，但累加器的位宽决定误差是否被放大。FP8 输入的矩阵乘通常以 FP32 或 FP16 累加：FP32 累加精度高但占用寄存器与带宽，FP16 累加快但在长归约（如大 $d$ 的注意力内积）上会累积舍入误差。视觉编码器的卷积与投影层归约长度中等，FP16 累加一般够用；跨模态注意力的内积归约长度等于压缩后的视觉 token 数，若压缩比例高、序列仍长，FP16 累加的误差会在 softmax 前被指数放大。</p>\n<p>误差传播的路径值得单独看：视觉编码器的量化误差进入 token 特征，版面头在此基础上预测角色与偏置，偏置误差再进入注意力分布，最终影响自回归生成的每个 token。这条链上每一环都在放大前一环的误差，而 LayoutLite 的结构把版面理解与文本识别压进同一次前向，意味着没有独立的检测阶段来吸收或纠正视觉侧的量化误差。显式版面分析路径虽然串行、慢，但它用独立的检测模型做了一次“重新感知”，某种程度上隔离了识别模型的数值误差；隐式路径取消了这个隔离层，精度方案必须更保守。</p>\n<p>代价侧：FP32 累加器在 Tensor Core 流水线中占用更多寄存器，降低每 SM 的并发 warp 数，直接影响视觉编码器的吞吐。工程上常见的折中是分阶段设置——视觉主干矩阵乘用 FP16 累加，注意力 softmax 前的分数用 FP32 累加再转回低精度，版面头的 logits 归约用 FP32。这种混合累加策略的显存代价可忽略，但需要 kernel 层面区分累加器类型，CUTLASS 与 Triton 都支持按算子配置累加精度。</p>\n<p>具体例子：表格密集的文档页，单元格边界 token 的视觉特征差异小，若视觉编码器用 FP8 且 FP16 累加，边界 token 的特征在归约后可能趋同，版面头把它们判为同一角色，解码器生成的表格文本丢失行列结构。把这一层的累加切到 FP32，特征区分度恢复，代价是该层吞吐下降——这正是精度与吞吐在文档 OCR 上的直接权衡点。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-16\">十六 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 的推理含义</h3>\n<p>Blackwell 的第五代 Tensor Core 引入 tcgen05 指令族，配套的是 TMEM（Tensor Memory）——一块与寄存器文件分离、专供矩阵乘累加器使用的高速存储。传统 MMA 的累加器占用寄存器，大矩阵乘时寄存器压力限制并发；TMEM 把累加器搬出寄存器文件，使 Tensor Core 能以更大的 tile 持续运算，同时释放寄存器给其他算子。对 LayoutLite 的推理含义是：视觉编码器的大矩阵乘（如 patch embedding 投影、注意力 QKV 投影）可以用更大的 tile 一次算完，减少 kernel 启动与中间结果落显存的次数；跨模态解码器的权重矩阵乘同样受益，尤其在批内页数多、解码并行走宽时。</p>\n<p>2-SM MMA 是另一项关键特性：两个 SM 协作完成一次矩阵乘，共享操作数与累加器，等效于把 MMA 的 tile 尺寸翻倍。它降低的是每个输出元素摊到的操作数读取次数，提升算力利用率，代价是要求两个 SM 的调度同步、对批大小与序列长度的对齐更敏感。LayoutLite 的批调度按页数与视觉 token 预算对齐，压缩后的序列长度决定单批页数——这个对齐恰好是 2-SM MMA 发挥效用的前提：序列长度与批大小若能对齐到 tile 边界，2-SM MMA 的吞吐收益才能兑现；对齐不佳时，尾部 tile 的浪费会抵消收益。</p>\n<p>显存与带宽代价要单独算：TMEM 的容量有限，大 tile 的累加器占用会限制同时驻留的 MMA 数量，调度器需要在 tile 大小与并发之间取舍。视觉 token 压缩与合并模块缩短序列后，注意力矩阵乘的 tile 数减少，TMEM 压力下降，但压缩本身是一次额外的相似度计算与 gather，其带宽开销与压缩比例成正比。工程判断是：压缩比例高到让序列长度对齐 tile 边界时，压缩的带宽开销能被后续 MMA 的吞吐收益覆盖；压缩比例过低则两头不讨好。</p>\n<p>具体例子：一页多栏报纸，视觉 token 网格密集，压缩合并后序列长度落在 2-SM MMA 的 tile 边界附近，视觉编码器与解码器的矩阵乘都能跑满两个 SM 的协作通路；若压缩后序列长度偏离边界，尾部 tile 只有单 SM 工作，整批的有效算力利用率下降。这解释了为什么批调度要按 token 预算对齐，而不是简单按页数装箱。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-17\">十七 · 量化方案与回退路径的联合校准</h3>\n<p>LayoutLite 的失败模式是版面头置信度低于阈值或输出顺序冲突时回退到显式版面分析路径。这条回退路径对量化方案提出额外约束：回退样本要走独立的检测模型与区域裁剪，其显存峰值与串行延迟会叠加在主路径之上。若主路径用 NVFP4 把显存压得很低，回退路径的显存需求反而成为峰值——高回退率下，批调度被迫为主路径与回退路径同时预留显存，量化省下的显存被回退路径吃掉。</p>\n<p>校准的顺序应当是：先定回退阈值，再定量化精度。阈值定得低，回退率低，主路径可以用更激进的精度；阈值定得高，回退率高，主路径的精度下探空间被压缩，因为回退路径的显存与延迟预算必须留足。版面头置信度本身受量化影响——低精度让 logits 分布变平，置信度整体下移，阈值不变时回退率被动升高。这是一个闭环：量化降低精度、精度降低置信度、置信度触发回退、回退拉高尾延迟。部署前必须用真实文档分布校准这条链，而不是分别调量化参数与回退阈值。</p>\n<p>代价侧：回退路径的显存峰值通常高于主路径的单页推理，因为它要加载检测模型并保留裁剪后的区域图像。批调度若按主路径的显存占用装箱，回退样本到来时会触发重调度或显存溢出。工程做法是把回退率作为批调度的输入变量，按页数与回退概率预留显存余量，代价是单批可容纳页数下降、吞吐略降，换取尾延迟可控。</p>\n<p>具体例子：公式与表格混排的文档页，版面头置信度普遍偏低，回退率高于纯文本页。若整批混装这两类页，批内序列长度方差大，回退样本的串行检测拖慢整批的首 token 延迟。按版面头置信度分流组批——高置信度页走激进量化与紧凑装箱，低置信度页单独组批并预留回退显存——是把量化精度与回退路径解耦的可行手段，代价是批的碎片化与调度复杂度上升。</p>\n<p>最后落在具体机制上：LayoutLite 的数值精度方案不能孤立地按算子选型，视觉编码器的 FP8/NVFP4 选择、版面头的累加精度、注意力偏置的量化粒度、回退阈值的设定，四者通过置信度与回退率耦合在一起。Blackwell 的 tcgen05 与 TMEM 给的是算力与 tile 尺寸的空间，2-SM MMA 给的是对齐前提，而文档 OCR 的精度底线由 token 级版面信号的区分度决定——精度下探的边界不在 Tensor Core 的吞吐曲线上，而在版面头能否在低精度下仍把相邻 token 的版面角色分开。</p>\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-18\">十八 · 显存账本的三个账户与可复算预算</h3>\n<p>在 Blackwell 上给 LayoutLite 做容量规划，第一步不是问“模型多大”，而是把单次前向的显存拆成三个互不相同的账户：权重（静态、跨请求共享）、激活（瞬时、随前向峰值起落）、KV cache（跨解码步累积、随并发线性增长）。三者失效模式不同——权重不足是加载失败，激活不足是编译期或运行期 OOM，KV cache 不足则表现为批被截断或请求被拒，直接打到 SLO 上。工程上必须分开算，因为它们的压缩手段完全不同：权重靠量化，激活靠分块与重算，KV 靠分页与压缩。</p>\n<p>设视觉编码器参数量 $P_v$、解码器参数量 $P_d$，权重字节数为 $B_w = (P_v+P_d)\\cdot b_w$，其中 $b_w$ 是每参数字节。FP8 下 $b_w=1$，NVFP4 下权重主体约 0.5 字节/参数，但需为每 16 元素一组的缩放因子留出额外字节，实际打包后略高于 0.5。激活峰值可写成 $B_a \\approx N_{\\text{tok}}\\cdot d\\cdot b_a\\cdot k_a$，$N_{\\text{tok}}$ 是单次前向的最大序列长度（视觉 token 与文本历史之和），$d$ 是隐藏维，$k_a$ 是框架的激活放大系数（注意力中间缓冲、归一化临时量、通信缓冲）。KV cache 是这本账里唯一随并发增长的项：</p>\n<div class=\"formula\">$$B_{\\mathrm{kv}} = 2 \\cdot L \\cdot H_{\\mathrm{kv}} \\cdot d_h \\cdot b_{\\mathrm{kv}} \\cdot N_{\\mathrm{ctx}} \\cdot C$$</div>\n<p>系数 2 是 K 与 V 两份，$L$ 为层数，$H_{\\mathrm{kv}}$ 为 KV 头数（GQA 下远小于查询头数），$d_h$ 为头维，$b_{\\mathrm{kv}}$ 为 KV 精度字节，$N_{\\mathrm{ctx}}$ 为单请求上下文长度，$C$ 为并发请求数。LayoutLite 的关键结构性收益就落在 $N_{\\mathrm{ctx}}$ 上：压缩合并模块把视觉 token 序列缩短，视觉部分对 KV 的贡献按压缩比线性下降，而文本历史部分不受影响。</p>\n<p>给一个可复算的例子（假设值，仅用于演示算术，非实测）：解码器 32 层、8 个 KV 头、头维 128、KV 用 FP8（$b_{\\mathrm{kv}}=1$）。每 token 每请求的 KV 字节为 $2\\times32\\times8\\times128\\times1 = 65536$ 字节，即 64 KiB/token。若压缩后视觉 token 为 1024、文本历史上限 512，则单请求 $N_{\\mathrm{ctx}}=1536$，KV 约 96 MiB。HBM3e 单卡容量按 141 GB 档（B200 量级）计，扣掉权重与激活后若剩 100 GB 可用于 KV，则理论上限约一千个并发请求——但这是容量上限，不是吞吐上限，真正的约束在下一节的带宽。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-19\">十九 · 分页：把 KV 从连续块变成可拼装的页</h3>\n<p>连续分配的 KV 缓冲有两个工程病灶：内部碎片（按最大长度预留，短请求浪费）与外部碎片（变长请求反复分配释放）。分页 KV cache 把每个请求的 KV 切成固定 token 数的页（常见 16 或 32 token 一页），页表记录逻辑位置到物理页的映射，分配以页为单位、按需增长。对 LayoutLite 而言，分页带来一个额外好处：视觉 token 与文本 token 的页可以分开管理，视觉页在压缩后一次性写入、之后只读，文本页则逐步追加，两类页的生命周期不同，混在连续缓冲里会互相拖累。</p>\n<p>伪代码思路：请求到达时按压缩后视觉 token 数预分配视觉页，解码每步追加文本页；页满则从空闲池取新页，请求结束整批归还。代价是页表查表开销与注意力核的间接寻址——分页注意力的读带宽不再是顺序流，页表命中率与页大小直接决定有效带宽利用率。页太小，页表膨胀、寻址开销上升；页太大，短请求尾部浪费。工程判断是：视觉 token 压缩比越高，视觉页数越少，页大小可以取大以减少页表项；文本侧仍按小页以适配变长输出。</p>\n<p>显存侧的账要重算：分页把“按最大长度预留”改为“按实际页数占用”，峰值显存从 $C\\cdot N_{\\max}$ 降到 $\\sum_i N_i$ 加上页表与池碎片。批调度因此可以把页数而非请求数作为准入条件——这正是 LayoutLite 按“页数与视觉 token 预算”组批的显存侧依据。回退路径是这本账的破坏项：回退样本要重新走显式版面分析，检测模型权重与中间激活在峰值时刻额外占一块，若回退率高，池中同时存在两套推理路径的激活，显存峰值不再是单路径峰值。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-20\">二十 · 压缩与复用：视觉 token 是唯一可压的变量</h3>\n<p>LayoutLite 的 KV 账本里，文本历史由自回归解码决定，不可压；视觉 token 是唯一可压的变量。压缩合并模块在编码后按相似度合并冗余 token，把 $N_v$ 降到 $N_v'=\\rho N_v$，$\\rho$ 为压缩比。对 KV 的直接影响是视觉部分字节按 $\\rho$ 缩放，对注意力的间接影响是跨模态注意力的键值读取量同比下降，解码每步的 KV 读带宽随之下降。但压缩不是免费的：$\\rho$ 过低会削弱细粒度版面表达，表格与公式混排区域的 token 被合并后，版面角色信号变得不可分辨，OCR 精度受损——这是精度与显存的直接兑换率，必须校准而非拍脑袋。</p>\n<p>复用有两个层次。其一是前缀复用：同一页文档若被多次请求（重试、多轮追问），压缩后的视觉 KV 页可缓存复用，跳过视觉编码与压缩合并，直接进入解码。其二是跨请求的页池复用：请求结束后视觉页若命中缓存键则保留，未命中则归还。复用把视觉编码的算力与显存一次性摊销到多次解码，代价是缓存管理本身的显存占用与命中率不确定性——缓存键怎么设计（图像哈希还是版面头输出指纹）决定命中率，也决定缓存会不会变成新的显存黑洞。</p>\n<p>量化是压缩的另一条轴，但必须与压缩比联合评估。KV 用 FP8 使 $b_{\\mathrm{kv}}$ 减半，直接砍掉一半 KV 字节；视觉编码器若也走 FP8，激活峰值下降但数值风险集中在版面头的分类置信度上——置信度偏移会改变回退率，回退率又反过来抬高尾延迟与显存峰值。这是一个闭环：精度选择影响回退率，回退率影响显存账，显存账影响批大小，批大小影响吞吐。部署前的校准必须把这个环走一遍，而不是单独测某一项的精度损失。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-21\">二十一 · 卸载：把冷页赶出 HBM，把热页钉住</h3>\n<p>HBM3e 容量再大也有边界，卸载是把 KV 页在 HBM 与主机内存（或远端存储）之间搬移。工程上分两级：被换出的页在需要时换回，被换入的热页优先保留。对 LayoutLite，视觉页天然是“写一次、读多次”的只读页，适合在显存紧张时整体换出到主机侧，解码需要时再按页换回；文本页则是持续追加的热页，换出代价高，应尽量钉在 HBM。换出决策的依据是页的访问频率与剩余解码步数，而非简单的 LRU——一个即将结束的请求，其历史文本页的剩余价值远低于一个刚开始长输出的请求。</p>\n<p>卸载的代价是 PCIe 带宽与延迟。一次页换入要占用主机到设备的传输时间，若换入发生在解码关键路径上，直接体现为首 token 延迟或步间抖动。因此卸载策略必须与批调度协同：把可能触发换入的请求排在批的前段，或提前预取。另一个代价是主机内存容量——卸载不是消除占用，是转移占用，主机侧池子不够时换出会失败，退化为拒绝请求。分离式预填/解码部署下，卸载还可以跨节点走 NVLink 或 RDMA，但跨节点换页的延迟量级远高于本地 PCIe，只适合冷页。</p>\n<p>一个具体判断：当压缩比 $\\rho$ 已经把视觉 KV 压到总 KV 的小头时，卸载的收益主要来自文本历史页而非视觉页；此时应优先做文本侧的页驱逐策略与请求准入控制，而不是把工程预算花在视觉页的换入换出上。反过来，若 $\\rho$ 接近 1（压缩几乎没起作用），视觉页就是卸载的主战场，且此时更该回头调压缩比而不是加卸载通道。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-22\">二十二 · 带宽瓶颈在哪：HBM3e 的读放大与有效带宽</h3>\n<p>解码阶段的算术强度极低：每生成一个 token，要把全部 KV 读一遍做注意力，计算量是 $O(N_{\\mathrm{ctx}})$ 的乘加，访存量是 $O(N_{\\mathrm{ctx}}\\cdot d)$ 的字节。于是瓶颈从算力转到 HBM 读带宽。HBM3e 的堆栈带宽按每堆栈约 1.2 TB/s 量级、单卡多堆栈聚合到数 TB/s 档，但这是理论峰值；有效带宽要扣掉三件事：分页注意力的非顺序访问造成的行激活开销、页表与元数据的额外读、以及多请求交织时的缓存抖动。读放大系数 $\\alpha$ 定义为实际读字节与理论 KV 字节之比，$\\alpha&gt;1$ 的部分全是工程损耗。</p>\n<div class=\"formula\">$$\\mathrm{TPOT} \\gtrsim \\frac{\\alpha \\cdot B_{\\mathrm{kv,step}}}{BW_{\\mathrm{eff}}},\\quad B_{\\mathrm{kv,step}} = 2 L H_{\\mathrm{kv}} d_h b_{\\mathrm{kv}} N_{\\mathrm{ctx}}$$</div>\n<p>把第一节的例子代进来：单请求每步 KV 读约 96 MiB（$N_{\\mathrm{ctx}}=1536$），若有效带宽按 3 TB/s 量级、$\\alpha=1.2$，单请求每步下限约 38 微秒；但单请求远填不满带宽，必须靠批把多个请求的 KV 读拼成连续流。批大小 $C$ 增大时，每步读字节线性增长，TPOT 下限随之上升，直到带宽饱和——这就是为什么 KV 压缩比直接换成吞吐：$\\rho$ 降一半，视觉部分读字节减半，同样带宽下可容纳更多并发或更低 TPOT。</p>\n<p>带宽瓶颈还有一个隐蔽来源：跨模态注意力读的是压缩后的全页视觉 token，而不是按框裁剪的小块。省掉裁剪意味着单次读的字节数比裁剪路径多，但省掉了重复视觉编码与检测模型的访存——净效果取决于压缩比。若 $\\rho$ 高，全页读的字节量与裁剪读相当甚至更少；若 $\\rho$ 低，全页读反而更贵。这是 LayoutLite 在带宽账上最需要实测的一个兑换点，材料未给数值，部署时必须用页级 profiler 量 $\\alpha$ 与每步读字节，而不是凭结构推断。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-23\">二十三 · 容量规划：从 SLO 反推页预算</h3>\n<p>容量规划的正确顺序是从 SLO 反推，而不是从显存正推。给定首 token 延迟上限与 TPOT 上限，先由带宽公式定出单批可承受的每步读字节上限，再除以单请求 $N_{\\mathrm{ctx}}$ 得到批内请求数上限；再由显存账本核对该批的 KV 页数是否装得下，装不下则降批或提压缩比。两个约束取小者，才是真实容量。回退率作为第三个约束进入：回退样本的额外激活与检测模型权重占用要从可用显存里预留，预留比例按监控到的回退率分布设定，而不是按平均值——尾延迟由高分位回退率决定。</p>\n<p>具体做法是把预算写成一张可复算的表：权重（按精度与参数量）、激活峰值（按最大序列与 $k_a$）、KV 每 token 字节（按层数、KV 头数、头维、精度）、页开销（页表与池碎片按百分比预留）、回退预留（按回退率分位）。每一项都乘以安全系数后求和，与 HBM3e 可用容量比对。这张表的价值不在数字本身，而在每一项都能被单独 profiler 验证：若实测激活峰值远超预算，说明 $k_a$ 估错或框架有隐藏缓冲；若实测 KV 字节高于公式，说明分页碎片或页表开销被低估。</p>\n<p>最后落在工程判断上：LayoutLite 的显存账本里，权重与激活是常量级，KV 是唯一随并发伸缩的项，而 KV 中视觉部分是唯一可压的项——所以容量规划的自由度几乎全部集中在压缩比 $\\rho$、KV 精度 $b_{\\mathrm{kv}}$ 与回退率三者构成的三角上。三者不能独立调：提 $\\rho$ 省显存但伤精度、抬回退率；降 $b_{\\mathrm{kv}}$ 省显存但扰动版面头置信度、同样抬回退率；回退率一升，尾延迟与显存峰值同时恶化，把前两项的收益吃掉。部署时应当把这三个量放进同一个校准回路，用页级 profiler 同时观测压缩后序列长度、KV 每步读字节与回退率分布，任何一项偏离预算就回退到上一组参数，而不是单点调优某一项。</p>\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-24\">二十四 · 连续批处理：以 token 预算而非请求数为组批单位</h3>\n<p>LayoutLite 把版面检测从串行前置模块改为 token 级并行信号之后，调度器的组批自由度发生了实质变化：整页图像只做一次视觉编码，视觉 token 序列长度由压缩合并模块决定，解码阶段的 KV cache 只保留压缩后的视觉 token 与文本历史。于是组批的约束不再是\"每批能塞多少张图\"，而是\"每批的视觉 token 预算与文本 token 预算之和能否对齐到解码器的并行度\"。连续批处理在这里的含义是：解码器每步迭代从活跃请求集合中取出一批 token，视觉 token 在请求进入时一次性写入 KV cache 并常驻，文本 token 随自回归逐步追加。调度器维护一个 token 预算 $B$，每接受一个请求就扣减其压缩后视觉 token 数 $n_v^{(i)}$ 与预估文本长度 $\\hat{n}_t^{(i)}$：</p>\n<div class=\"formula\">$$\\sum_{i\\in \\mathcal{A}} n_v^{(i)} + \\sum_{i\\in \\mathcal{A}} \\hat{n}_t^{(i)} \\le B,\\qquad \\text{admit}(i)\\ \\text{iff}\\ B-\\sum_{j\\in\\mathcal{A}}\\left(n_v^{(j)}+\\hat{n}_t^{(j)}\\right)\\ge n_v^{(i)}+\\hat{n}_t^{(i)}$$</div>\n<p>这个判据的直接代价是显存：视觉 token 常驻 KV cache 意味着即使请求处于解码中段，其视觉部分也占着显存不放，单批可容纳页数由压缩比与预算共同决定。具体例子：一页双栏论文经压缩合并后视觉 token 数为 $n_v$，若预算 $B$ 只够容纳若干页，则调度器会优先接纳压缩比高、版面简单的页，把表格与公式混排页推到下一批——这不是公平性问题，而是批内序列长度方差直接转化为解码步的无效计算。工程判断是：把压缩比作为准入排序键之一，比按到达时间先到先服务更能压低批内方差。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-25\">二十五 · Chunked prefill：把视觉编码与解码切开做时间片</h3>\n<p>LayoutLite 的链路里，\"prefill\"包含两段性质不同的工作：视觉编码器对整页图像的单次前向，以及解码器对压缩视觉 token 的跨模态注意力预填。前者是计算密集的卷积/注意力混合负载，后者是带宽密集的 KV 写入。若把整页 prefill 与解码请求混在同一迭代里，视觉编码的长前向会阻塞解码步，抬高已在解码中的请求的 token 间延迟。Chunked prefill 的做法是把视觉编码按网格切块，或将多页的编码前向拆到多个调度时间片，与解码步交替执行：每个迭代先跑一个解码步（对所有活跃请求各出一 token），再跑一个视觉编码块。伪代码思路：</p>\n<ul>\n<li>迭代开始：对活跃解码集合执行一步自回归，写 KV；</li>\n<li>若待编码队列非空且本迭代 token 预算有余量，取一页的一个网格块做视觉前向，产出视觉 token 并压入暂存；</li>\n<li>一页的全部网格块编码完成且压缩合并结束后，才把该请求标记为可解码，其视觉 token 一次性写入 KV cache；</li>\n<li>版面头置信度低于阈值的请求在编码完成时即被分流到回退路径，不进入解码批。</li>\n</ul>\n<p>代价落在首 token 延迟上：一页被切成 $c$ 块、每块占一个迭代，则该请求的首 token 延迟约等于 $c$ 个迭代周期加上一次解码步，而吞吐收益来自解码步不再被长前向打断。具体例子：当批内已有若干请求在解码、新到页的视觉编码需要数个时间片时，chunked prefill 让在解码请求的 token 间延迟保持平稳，代价是新页的首 token 延迟被拉长——这正是文档 OCR 服务里\"整页生成时延\"与\"首 token 延迟\"两个 SLO 指标需要分开设阈值的原因。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-26\">二十六 · 优先级与抢占：按版面头置信度分流</h3>\n<p>LayoutLite 的失败模式是版面头置信度低于阈值或输出顺序冲突时回退到显式版面分析路径。回退路径会重新引入检测模型与区域裁剪，其延迟与显存占用远高于隐式路径，且是串行的。若回退样本与正常样本混在同一批里，整批的解码步会被回退路径的串行检测拖慢，尾延迟被少数样本拉高。因此优先级调度应以版面头置信度为核心信号：置信度高的页进入快车道批，置信度接近阈值的页进入观察批（先编码、后判定），低于阈值的页直接进入回退队列单独调度。抢占策略上，当显存峰值逼近上限时，调度器应抢占解码进度最浅、已生成文本最短的请求，将其 KV cache 换出到主机侧，腾出空间给回退路径的检测模型——因为回退路径的显存需求是突发性的，而解码请求的 KV 可以重建。代价是换出再换入带来一次 KV 读写带宽开销，收益是避免回退路径因显存不足而排队。具体例子：一批混排文档中若回退率偏高，快车道批的吞吐不受影响，但回退队列的排队长度会直接体现在整页生成时延的 P99 上，监控项应把回退率与回退队列等待时间并列。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-27\">二十七 · 分离式预填/解码：把视觉编码与自回归拆到不同卡</h3>\n<p>LayoutLite 的推理链路天然分成两段异构负载：视觉编码器是整页单次前向、计算密集、无 KV 状态；跨模态解码器是自回归、带宽密集、KV cache 随生成增长。分离式预填/解码把这两段部署到不同卡组：编码卡组只跑视觉前向与压缩合并，产出压缩视觉 token 后经高速互联传给解码卡组；解码卡组只做自回归与跨模态注意力，KV cache 仅含压缩视觉 token 与文本历史。传输量是压缩后的视觉 token 张量，其大小由压缩比决定，压缩比越高，跨卡传输带宽压力越小。代价是两段之间的传输延迟被计入首 token 延迟，且编码卡组与解码卡组的利用率曲线不同步——编码卡组在负载低谷会闲置，解码卡组在长文档生成时会成为瓶颈。工程判断：按页数与 token 预算的比例配置两组的卡数，使编码吞吐与解码吞吐匹配；在 NVLink 域内做这种拆分时，传输开销可被压缩比摊薄，跨域拆分则需要重新评估。具体例子：当解码卡组的 KV cache 因长文档生成而逼近上限时，编码卡组可以提前把后续页的视觉 token 压缩到更短，用压缩比换解码侧的显存余量，这是分离式部署独有的调节旋钮。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-28\">二十八 · 尾延迟怎么压：三个可操作的杠杆</h3>\n<p>文档 OCR 的尾延迟来源在 LayoutLite 下被重新分布：串行检测延迟消失，但回退路径、批内序列长度方差、压缩过度导致的精度返工成为新的长尾。压尾延迟的第一个杠杆是准入控制：按压缩后视觉 token 数与版面头置信度做双键排序，把高方差页隔离到独立批，避免它们拉长正常批的解码步。第二个杠杆是回退路径的预取：对置信度处于阈值边缘的页，在编码阶段就并行启动轻量检测模型的预热，若判定回退则检测已就绪，若判定不回退则丢弃预热结果——用少量冗余计算换回退路径的启动延迟。第三个杠杆是压缩比的动态调节：对批内已积压的请求，临时提高压缩合并的相似度阈值以缩短视觉序列，换取解码步的吞吐；代价是细粒度表格与公式的版面表达被削弱，需以精度监控为约束。三个杠杆的共同代价是显存与带宽的重新分配，收益体现在 P99 整页生成时延上。具体例子：当回退队列长度超过阈值时，调度器应暂停接纳新的低置信度页，先把回退队列清空，否则回退路径的串行检测会与正常批的解码争抢同一张卡的显存带宽，尾延迟呈非线性上升。</p>\n<table class=\"mini\"><thead><tr><th>调度手段</th><th>主要收益</th><th>主要代价</th><th>监控项</th></tr></thead><tbody><tr><td>连续批处理按 token 预算组批</td><td>批内序列长度方差下降，解码步利用率上升</td><td>视觉 token 常驻 KV，单批页数受压缩比约束</td><td>批内序列长度方差、单批页数</td></tr><tr><td>Chunked prefill</td><td>解码步不被视觉长前向阻塞</td><td>新页首 token 延迟随切块数线性增加</td><td>首 token 延迟、切块数</td></tr><tr><td>按置信度优先级与抢占</td><td>回退样本不拖慢正常批</td><td>KV 换出再换入的带宽开销</td><td>回退率、回退队列等待时间</td></tr><tr><td>分离式预填/解码</td><td>两段异构负载各自满负荷</td><td>跨卡传输延迟计入首 token 延迟</td><td>传输量、两组卡利用率</td></tr></tbody></table>\n<p>这张表里没有一行能单独把尾延迟压下去：连续批处理压的是批内方差，chunked prefill 压的是解码步阻塞，优先级压的是回退污染，分离式部署压的是资源争抢。四者叠加时，调度器的决策顺序应为：先按置信度分流，再按 token 预算组批，再在批内插入编码时间片，最后在显存逼近上限时触发抢占。任何一步的顺序颠倒都会让另一部的代价显性化——例如先组批再分流，回退样本已经占住 KV 再被踢出，换出开销白付一次。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-29\">二十九 · 批调度边界：压缩比、回退率与尾延迟的三方拉扯</h3>\n<p>LayoutLite 把批调度的对齐维度从“检测框数量”换成“页数与视觉 token 预算”，压缩合并模块的输出长度直接决定单批可容纳页数。设第 i 页压缩后视觉 token 数为 <span class=\"inline-math\">s<sub>i</sub></span>、文本历史预算为 <span class=\"inline-math\">T</span>，则单批可行性约束可写成 <span class=\"inline-math\">Σ<sub>i</sub>(s<sub>i</sub>+T) ≤ C<sub>kv</sub></span>，其中 <span class=\"inline-math\">C<sub>kv</sub></span> 为 KV cache 容量上限。问题在于 <span class=\"inline-math\">s<sub>i</sub></span> 随版面复杂度波动：多栏与表格页合并后仍偏长，纯文字页则被压得很短，批内方差大意味着按均值组批会频繁触发重排或空转，按最大值组批又浪费显存。工程上应把压缩比与页数一起作为调度键，而非只按请求到达顺序做连续批处理。</p>\n<p>回退路径是这套调度最脆弱的环节。版面头置信度低于阈值或顺序冲突的样本会被拉回显式版面分析，这条路径带检测模型与区域裁剪，延迟量级与主链路不同，且显存峰值更高。若回退样本与正常样本混在同一连续批中，整批的迭代节奏被最慢样本拖住，尾延迟由回退率而非平均页数决定。可行做法是按置信度分流：高置信样本走 token 级链路并允许更激进的 chunked prefill 切分，低置信样本单独成批或直接路由到显式路径，避免抢占式调度在解码中途反复换入换出、抬高 KV cache 换入带宽。</p>\n<p>分离式预填/解码在这里的收益与风险并存。视觉编码器单次整页前向是典型的计算密集预填段，自回归解码则是访存密集段，二者分卡部署可隔离延迟，但也把压缩后视觉 token 与文本历史经 NVLink 搬运，跨卡 KV 传输量随批内页数线性增长。当压缩比不足、<span class=\"inline-math\">s<sub>i</sub></span> 偏大时，传输带宽会成为新的瓶颈，抵消省去二次编码带来的收益。因此压缩比例必须与分离式拓扑联合标定：压缩过强会削弱细粒度表格与公式的 token 级表达力，压缩不足则让 KV 传输吃掉调度红利。</p>\n<table class=\"mini\"><thead><tr><th>调度键</th><th>收益侧</th><th>代价侧</th></tr></thead><tbody><tr><td>按页数组批</td><td>实现简单，预填段整齐</td><td>忽略 s<sub>i</sub> 方差，显存易溢出</td></tr><tr><td>按 token 预算组批</td><td>KV 占用可控，批内均衡</td><td>需在线估计压缩后长度</td></tr><tr><td>按置信度分流</td><td>压住回退带来的尾延迟</td><td>小批增多，吞吐下降</td></tr></tbody></table>\n<p>部署判断落在监控项而非静态配置：版面头置信度分布、回退率、压缩比与批内序列长度方差必须在线可见，SLO 应同时约束首 token 延迟与整页生成时延。材料未给出量化方案与硬件档位，NVFP4/FP8 对视觉编码器与跨模态注意力的数值影响无法定量评估，压缩比与精度需在 Blackwell 上自行校准后再定调度阈值——把回退阈值调低能压尾延迟，却会把精度风险转嫁给显式路径的串行开销。</p>\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-30\">三十 · 从“单卡单页”到“多卡多页”：LayoutLite 的切分对象是什么</h3>\n<p>LayoutLite 的推理链路只有两段重活：视觉编码器对整页图像的一次前向，以及跨模态解码器的自回归生成。切分策略必须围绕这两段各自的资源画像来定，而不是套用 LLM 的默认拓扑。视觉编码器是计算密集、序列固定、无 KV 状态的整页前向，天然适合张量并行（TP）与数据并行（DP）；解码器是访存密集、KV cache 随生成增长的自回归段，适合 TP 加流水并行（PP）来分摊层数与显存。真正特殊的是版面头：它在视觉 token 序列维度上预测版面角色与阅读顺序偏置，输出的是与序列等长的偏置向量，这个向量的切分必须与视觉 token 的切分严格对齐，否则注入跨模态注意力时会出现角色错位。</p>\n<p>具体机制上，视觉编码器按 TP 切分时，每层注意力的头维度被均分到各卡，All-Reduce 在每层前后各发生一次；版面头若跟随 TP 切分，则其分类头权重按 token 维度切分，各卡只负责自己那段 token 的角色预测，偏置向量在序列维拼接而非求和。压缩合并模块按相似度合并冗余 token，这一步是序列长度可变的操作，跨卡合并需要一次 All-to-All 交换候选合并对，代价随压缩比上升而下降——压缩越狠，后续解码段的通信量越小。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\underbrace{\\frac{2 \\cdot P \\cdot B \\cdot S}{F_{\\text{card}}}}_{\\text{计算}} + \\underbrace{\\frac{2 \\cdot (N-1)}{N} \\cdot \\frac{V_{\\text{act}} \\cdot L}{B_{\\text{link}}}}_{\\text{TP All-Reduce}}$$</div>\n<p>其中 $N$ 为 TP 度，$V_{\\text{act}}$ 为单层激活字节数，$B_{\\text{link}}$ 为链路有效带宽。这个式子给出一个工程判断：当单页视觉 token 数不大、编码器层数有限时，TP 的 All-Reduce 项占比会被计算项压住；但一旦把 TP 度推到 8 以上而单卡算力未被喂饱，通信就开始吃掉延迟收益。一个具体例子：整页文档图像经编码后得到网格化视觉 token，压缩合并把序列缩短，若压缩比高，解码段每步只需读取压缩后的视觉 KV 与文本历史，此时 TP 的 All-Reduce 通信量随 $V_{\\text{act}}$ 同步下降，说明压缩与并行拓扑是耦合决策，不能分开调。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-31\">三十一 · NVLink 5 与 NVSwitch：机柜内域与域间边界</h3>\n<p>Blackwell 的 NVL72 机柜把 NVLink 5 与 NVSwitch 做成一个单跳全互联域，TP 与 EP 的集合通信落在这个域内时，All-Reduce 与 All-to-All 的代价主要由协议开销与消息大小决定，而不是由跳数决定。这对 LayoutLite 的意义在于：视觉编码器与解码器若同处一个 NVLink 域，跨段传递压缩后的视觉 token 与版面偏置几乎不构成瓶颈；一旦解码器被 PP 切到跨机柜，视觉 token 的传递就要走 NIXL 传输层，延迟量级跳变。</p>\n<p>机制上，NVSwitch 提供的是无阻塞的集合通信底座，All-Reduce 可用环形或树形算法，All-to-All 在 EP 场景下按 token 路由做点对点交换。LayoutLite 没有 MoE 结构，EP 不是它的主切分维度，但压缩合并模块的跨卡候选对交换、以及回退路径把样本重新分派到显式版面分析实例，都属于小消息 All-to-All 形态，这类通信对启动开销敏感，消息越小越容易被协议开销主导。</p>\n<table class=\"mini\"><thead><tr><th>切分维度</th><th>在 LayoutLite 中的落点</th><th>主要通信原语</th><th>代价敏感项</th></tr></thead><tbody><tr><td>TP</td><td>视觉编码器层内、解码器层内</td><td>All-Reduce</td><td>激活字节数、TP 度</td></tr><tr><td>PP</td><td>编码段与解码段分层</td><td>点对点激活传递</td><td>微批数、段间气泡</td></tr><tr><td>DP</td><td>不同页/不同批的副本</td><td>无（除权重同步）</td><td>批内序列长度方差</td></tr><tr><td>EP</td><td>非主路径；回退样本分派</td><td>All-to-All</td><td>消息粒度、回退率</td></tr></tbody></table>\n<p>工程代价的直接体现是显存与带宽的取舍：TP 度提高会降低单卡权重与激活占用，但每卡都要保存完整的 KV cache 分片，压缩后的视觉 KV 若未随 TP 切分对齐，会出现部分卡空转。一个具体例子：批调度按页数与视觉 token 预算组批，若批内某页版面复杂度高、压缩比低，其视觉序列显著长于同批其他页，TP 的 All-Reduce 会被这条最长序列拖到同步点，整批步进时间由最长页决定——这正是批内序列长度方差必须被预算对齐压住的通信侧原因。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-32\">三十二 · 通信何时成为瓶颈：三个可观测判据</h3>\n<p>第一个判据是计算通信比。视觉编码器单页前向的浮点运算量与参数量、token 数成正比，而 All-Reduce 的消息量与激活字节数成正比；当压缩合并把视觉序列压得很短，编码段每层的激活字节数下降，计算通信比反而恶化，此时提高 TP 度是负收益。第二个判据是批内方差：LayoutLite 的批按页数与 token 预算对齐，但版面复杂度差异会让压缩后的序列长度在批内分布很宽，同步式 All-Reduce 的等待时间由最长序列决定，方差越大，通信等待占比越高。第三个判据是回退率：版面头置信度低于阈值或输出顺序冲突的样本回退到显式版面分析路径，回退样本需要额外的检测模型前向与区域裁剪，若回退实例与主路径共享同一组卡，回退会以串行方式插入批处理节奏，尾延迟被拉长。</p>\n<div class=\"formula\">$$\\eta_{\\text{comm}} = \\frac{T_{\\text{comm}}}{T_{\\text{comm}} + T_{\\text{comp}}},\\quad T_{\\text{comm}} \\propto \\frac{S_{\\max} \\cdot V_{\\text{act}}}{B_{\\text{link}}},\\quad S_{\\max}=\\max_{i \\in \\text{batch}} S_i$$</div>\n<p>这里 $S_{\\max}$ 是批内最长压缩视觉序列，$S_i$ 是第 $i$ 页的序列长度。判据的用法很直接：监控 $\\eta_{\\text{comm}}$ 与批内 $S_{\\max}/S_{\\text{avg}}$ 的比值，当两者同时抬升时，说明瓶颈已从算力转到同步等待，此时应优先做序列长度对齐或按复杂度分桶，而不是继续加 TP 度。一个具体例子：多栏、表格、公式混排的文档页压缩比低，单栏纯文本页压缩比高，把两类页混在同一批里，$S_{\\max}$ 由混排页决定，纯文本页的卡在 All-Reduce 上纯等；按版面头置信度与压缩比分桶后，批内方差下降，通信等待随之收敛。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-33\">三十三 · NIXL 传输与分离式部署：视觉段与解码段的边界</h3>\n<p>LayoutLite 的链路天然适合分离式部署：视觉编码器做一次整页前向，输出压缩后的视觉 token 与版面偏置；解码器自回归生成文本，跨模态注意力读取全页 token。两段之间传递的是压缩后的视觉 KV 与偏置向量，而不是原始像素或检测框，这使传输量远小于把整页图像搬到解码实例。NIXL 在这里的角色是把视觉段产出的 KV 块以零拷贝或低拷贝方式注册并传输到解码段的显存，避免经过主机内存的往返。</p>\n<p>机制上，视觉段在编码与压缩合并完成后，把压缩视觉 token 的 KV 布局按解码器的 TP 切分做重排，再通过 NIXL 的点对点传输写入解码段对应卡的显存；版面偏置作为与序列等长的向量随 KV 一同传输，注入跨模态注意力时按 token 位置对齐。代价落在三处：传输延迟与视觉序列长度成正比，解码段首 token 延迟因此包含一次跨段传输；解码段需要预留接收缓冲，显存峰值由压缩视觉 KV 加文本历史决定；若视觉段与解码段算力配比失衡，解码段会因等待视觉 KV 而空转，反之视觉段会因解码段消费慢而积压。</p>\n<p>一个具体例子：批调度按页数与 token 预算组批后，视觉段一次前向产出整批的压缩视觉 KV，NIXL 按页粒度把各页 KV 分发到解码段的不同 TP 组；若某页因版面头置信度低被标记回退，其 KV 不进入解码段而转入显式版面分析路径，这条分流在传输层表现为一次小消息重定向，回退率上升会直接抬高传输层的消息数量与尾延迟。工程判断是：分离式部署的收益取决于视觉段与解码段的算力配比是否与负载的页数分布匹配，配比失衡时跨段传输会成为比 TP All-Reduce 更硬的瓶颈。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-34\">三十四 · 切分决策与回退路径的耦合</h3>\n<p>回退路径不是异常分支，而是并行拓扑设计的一部分。回退样本要跑显式版面分析，需要检测模型与区域裁剪，这条路径的显存占用与主路径不同，若与主路径共享 TP 组，回退会打断主路径的集合通信节奏；若单独分配实例，则回退实例在低回退率下利用率不足。可行的做法是按版面头置信度分流：高置信度样本走主路径的 TP 组，低置信度样本进独立的回退队列，回退队列按批聚合后再送检测模型，把串行插入变成批处理插入。</p>\n<p>机制上，版面头在 token 序列上输出角色与顺序偏置的同时给出置信度，调度器据此决定样本去向；回退队列的批大小由检测模型的显存与延迟特性决定，与主路径的页数预算解耦。代价是显存峰值出现在两条路径同时高负载的时刻，容量规划必须按主路径加回退路径的叠加峰值来算，而不是按主路径均值。一个具体例子：多栏表格混排页的版面头置信度分布偏低，回退率在这类页上抬升，若容量按均值规划，峰值时段回退实例排队会直接推高整页生成时延；按置信度分桶并把回退队列的批大小与主路径预算分开配置，才能把尾延迟压回 SLO 内。</p>\n<p>最后落在具体机制上：LayoutLite 的并行切分不应以 LLM 的 TP/PP/EP/DP 模板直接套用，而应以“视觉编码段计算密集、解码段访存密集、两段之间只传压缩视觉 KV 与偏置”这一事实为起点，先定压缩比与批内序列长度对齐，再定 TP 度与是否分离部署；通信瓶颈的判据是计算通信比、批内 $S_{\\max}/S_{\\text{avg}}$ 与回退率三者同时抬升，此时优先做分桶与压缩比校准，而不是加并行度。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-35\">三十五 · 并行切分的边界：当通信取代版面检测成为瓶颈</h3>\n<p>LayoutLite 把版面检测从串行前置模块压成 token 级注意力偏置，收益的前提是单卡能装下整页视觉 token 与解码器。一旦视觉编码器与自回归解码器跨卡切分，通信代价就会顶替被省掉的检测延迟。TP 切分跨模态注意力时，每层需对 qk^T 与输出投影做 All-Reduce，单 token 通信量约为 2×(hidden×tp−1)/tp 个元素；EP 切分 MoE 解码层则把 All-to-All 引入关键路径，其代价随批内 token 数与专家并行度线性上升。可用的判断式是：若单步通信时间 t_comm 超过解码单步计算时间 t_comp，则 TP/EP 的收益被抵消。PP 切分把视觉编码与解码分置不同 stage，天然隔离两段延迟，但 stage 间激活传输在 NVLink 5 上虽快，仍会引入气泡；DP 只复制权重、不切 token，对版面偏置注入无通信开销，是回退路径最友好的拓扑。</p>\n<p>NVLink 5 与 NVSwitch 决定 All-to-All 能否落在计算阴影内：机内 NVSwitch 全互联时，All-to-All 可与 MMA 重叠；跨机架则退化为 IB 传输，NIXL 的点对点拉取会把 KV 与视觉 token 的搬运暴露在关键路径上。分离式预填/解码部署下，压缩后的视觉 token 与文本 KV 经 NIXL 从预填节点传到解码节点，传输量正比于压缩比与批页数——压缩比越高，传输越省，但细粒度表格与公式的版面表达越弱，这是通信与精度之间的直接对冲。</p>\n<table class=\"mini\"><thead><tr><th>切分</th><th>关键通信</th><th>对 LayoutLite 的影响</th></tr></thead><tbody><tr><td>TP</td><td>每层 All-Reduce</td><td>跨模态注意力同步，压缩后序列短则通信占比升</td></tr><tr><td>EP</td><td>All-to-All</td><td>解码层专家路由，批内 token 方差放大通信</td></tr><tr><td>PP</td><td>stage 间激活</td><td>编码/解码隔离，气泡取决于微批对齐</td></tr><tr><td>DP</td><td>无</td><td>回退路径不引入额外集合通信</td></tr></tbody></table>\n<p>工程判断落在回退率上：版面头置信度低于阈值或顺序冲突的样本走显式检测路径，该路径若与主链共享 TP 组，检测模型的串行前向会打断 All-Reduce 节奏，尾延迟与显存峰值同时抬升；若把回退样本路由到独立 DP 副本，则需按回退率预留容量。监控项应包括回退率、压缩比、批内序列长度方差与单步通信占比，任一越界即说明并行拓扑已不适合当前版面复杂度分布。</p>\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-36\">三十六 · 精度塌陷：从版面头置信度到注意力偏置的失效链</h3>\n<p>LayoutLite 的精度塌陷不是均匀退化，而是沿一条可定位的链路传导：视觉编码器网格化 → 版面头角色预测 → 注意力偏置注入 → 跨模态注意力聚合 → 自回归输出。诊断的第一步是把这条链拆成可观测的中间量。版面头对每个视觉 token 输出角色分布与顺序偏置，若某页的角色预测熵显著高于批内中位数，说明该页的版面结构超出了 token 网格的表达力——典型场景是细粒度表格与公式混排，单元格边界落在两个 token 之间，角色信号被摊薄。此时注意力偏置 $b^{\\mathrm{layout}}$ 在 softmax 中只贡献微弱的排序倾向，解码器仍能生成文字，但阅读顺序开始漂移。</p>\n<p>量化塌陷程度可以用一个批内诊断量：对每页计算版面头角色分布的归一化熵与顺序偏置的符号一致率。顺序偏置在相邻 token 上应单调，若出现大量符号翻转，说明版面头在该页上不稳定。工程上把这两个量与 OCR 输出的字符级置信度做相关性监控，一旦相关性断裂，就说明塌陷发生在版面侧而非识别侧。代价上，这种监控本身要跑一次版面头前向并保留 token 级中间量，显存开销约为压缩后视觉序列的偏置张量大小，对批调度是可接受的常数项，但若逐页保留全量 token 级日志，日志带宽会成为瓶颈，需按页采样。</p>\n<p>具体例子：一页双栏加跨栏标题的文档，标题 token 被网格切成两段，版面头把后半段判为左栏正文，顺序偏置把标题后半段排到左栏末尾之后，解码器输出的标题被拆成两行错位文本。这类错误在字符置信度上往往不低，因为每个字都认得，错的是顺序。诊断必须落在顺序信号上，而不是只看识别置信度。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-37\">三十七 · OOM 与显存峰值：回退路径是隐藏的放大器</h3>\n<p>LayoutLite 的正常路径显存由三部分构成：整页视觉 token 的编码激活、压缩合并后的视觉序列、以及仅含压缩视觉 token 与文本历史的 KV cache。压缩合并模块按相似度合并冗余 token，直接压低 KV cache 中视觉部分的占用，这是它相对显式检测路径的显存优势。但 OOM 往往不发生在正常路径，而发生在回退路径：当版面头置信度低于阈值或顺序冲突触发回退时，样本要重新走显式版面分析——额外检测模型、区域裁剪、二次视觉编码同时在场，显存峰值叠加在原本已分配的批上。</p>\n<p>估算峰值可以用一个保守上界：设批内页数为 $B$，压缩后每页视觉 token 数为 $S_c$，回退页数为 $B_r$，则峰值显存近似正比于 $(B-B_r)\\cdot S_c + B_r\\cdot(S_c + S_{\\mathrm{det}} + S_{\\mathrm{crop}})$，其中后两项是检测激活与裁剪区域二次编码的占用。回退率 $r=B_r/B$ 直接决定这个上界的斜率。工程判断是：批调度必须把回退预算当作一等约束，而不是等 OOM 发生再降批。按版面头置信度分流——高置信页走隐式路径、低置信页单独组小批走回退——能把峰值压回可控区间，代价是分流带来的批内页数下降与吞吐损失。</p>\n<p>具体例子：一个按页数与视觉 token 预算对齐的批，原本容纳若干页，其中一页是密集表格触发了回退，检测模型与二次编码的激活把该批推过显存上限，整批失败重试。若调度器在组批前读取版面头置信度直方图并把该页移入回退专用小批，正常批不受影响，回退批以较低并发单独跑，尾延迟可控。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-38\">三十八 · 批抖动与尾延迟：序列长度方差是根因</h3>\n<p>批抖动表现为同一 SLO 下吞吐忽高忽低、首 token 延迟分布出现长尾。根因不是请求到达率的泊松波动，而是批内序列长度方差：压缩合并后的视觉序列长度因页面版面复杂度而异，多栏、表格、公式混排页的冗余 token 少、合并率低，序列更长；纯文本页合并率高、序列短。批调度按页数与 token 预算组批，但预算对齐只能约束总量，不能消除方差。解码阶段自回归步数与文本长度相关，视觉序列长度又影响每步跨模态注意力的计算量，两者叠加使批内各请求的完成时间离散化，短请求被长请求拖住，形成尾延迟。</p>\n<p>可操作的诊断量是批内压缩后序列长度的变异系数，以及每批的实际解码步数分布。当变异系数超过阈值，应改为按长度分桶组批，牺牲一点批大小换取方差收敛。另一个机制性因素是回退：回退样本走串行检测路径，其完成时间与隐式路径不在同一量级，混在同一批里会把整批的尾延迟拉到回退路径的水平。因此回退分流不只是显存策略，也是尾延迟策略。</p>\n<p>具体例子：一个混合批里多数是单栏文本页、少数是跨页表格，短页在视觉 token 上很快编码完，但要等表格页的自回归解码走完才能整批释放，首 token 延迟对短页而言被无谓拉长。按压缩后长度分桶后，短页批的解码步数集中，尾延迟分布收窄。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-39\">三十九 · 静默降级：不报错但输出变差的三种形态</h3>\n<p>静默降级是 LayoutLite 部署中最危险的一类失败，因为监控指标不报警、请求成功返回，但输出质量已滑落。可识别的形态有三种。其一是压缩过度：视觉 token 合并比例调高后，细粒度版面信号被合并掉，表格单元格与公式上下标的角色区分消失，OCR 仍输出连贯文本但结构错乱。其二是量化未校准：材料未给出量化方案与硬件档位，NVFP4/FP8 对视觉编码器与跨模态注意力的数值影响无法定量评估，若直接把低精度套到注意力偏置上，微小的偏置误差会在 softmax 中被放大成顺序漂移。其三是回退阈值漂移：阈值设得过高使大量本可走隐式路径的样本回退，系统看似正常但延迟结构已变；阈值设得过低则让低置信样本硬走隐式路径，错误被静默吞下。</p>\n<p>监控静默降级不能只看端到端成功率，要建立代理指标：版面头置信度分布的均值与低分位、压缩比的实际分布、回退率的滑动窗口、以及输出文本的阅读顺序一致性抽检。阅读顺序一致性可以用一个轻量规则——按隐式顺序信号拼接后的文本，其段落边界与页面几何的粗匹配率——作为在线探针。代价是探针本身要跑少量几何比对，属于 CPU 侧开销，不影响 GPU 批调度。</p>\n<p>具体例子：压缩比从保守值上调后，吞吐上升、错误率不变，但抽检发现表格页的列顺序在输出中被交错。这就是压缩过度导致的静默降级，端到端指标看不见，只有压缩比分布与顺序一致性探针能定位。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-40\">四十 · 监控面与回滚：把回退率当作一等 SLO 信号</h3>\n<p>监控面应按链路分层布置。编码层看视觉 token 数与压缩比分布；版面层看角色分布熵、顺序偏置符号一致率、置信度直方图；解码层看首 token 延迟、每请求解码步数、KV cache 中视觉部分占比；调度层看批内序列长度变异系数、回退分流批的排队时长。把这些量与 SLO 绑定：首 token 延迟与整页生成时延是主 SLO，回退率与压缩比是领先指标——它们先动，主 SLO 后动，领先指标给回滚留出时间窗。</p>\n<p>回滚要分级而不是一刀切。第一级回滚是调回退阈值，把低置信样本重新纳入显式路径，代价是尾延迟上升但精度恢复；第二级是调压缩比，回到保守合并率，代价是 KV cache 占用上升、单批页数下降；第三级是整体切回显式版面分析流水线，放弃 token 级隐式信号，代价是串行检测延迟与二次编码显存全部回归。分级的意义在于每一级都有明确的代价函数，运维能按 SLO 缺口选择最小代价的回滚点。回滚触发条件应是领先指标的持续偏离，而非单点毛刺，否则会在正常方差上反复抖动。</p>\n<p>具体例子：版面头置信度低分位连续多个窗口下移、回退率同步上升，而首 token 延迟尚未破线。此时执行第一级回滚调阈值，把回退率压回基线，避免尾延迟在下一波流量峰值时破线。若压缩比分布同时异常，则升级到第二级。这套分级把“精度塌陷—OOM—批抖动—尾延迟—静默降级”五类失败模式收敛到同一套可观测量与回滚动作上，使 LayoutLite 的隐式版面信号在 Blackwell 部署中可运维，而不是只能靠端到端指标事后归因。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-41\">四十一 · 失败模式与诊断：从回退率到批内方差的观测闭环</h3>\n<p>LayoutLite 的失效不是单点崩溃，而是沿“版面头置信度—压缩比—批形状”三条链传导。最典型的静默降级是：版面头置信度略高于阈值、顺序信号却局部冲突，解码器仍按自回归生成，输出文本可读但阅读顺序错乱，端到端 OCR 指标缓慢下滑而服务指标毫无异常。诊断上应把版面头置信度分布、回退率、压缩比与批内序列长度方差做成同一条监控曲线：回退率抬升通常先于精度塌陷出现，因为低置信度样本被分流到显式检测路径，掩盖了隐式路径的表达力不足。精度塌陷的定位顺序是：先看压缩比是否被调度器为塞进更多页数而调高，再看网格粒度是否因预处理缩放而变粗，最后才怀疑量化——材料未给出量化方案，NVFP4/FP8 对视觉编码器与跨模态注意力的数值影响需自行校准，不能默认与显式检测路径等价。</p>\n<p>OOM 与批抖动同源：批调度按页数与视觉 token 预算组批，但压缩后的序列长度才决定单批页数，版面复杂度差异直接表现为批内方差。设第 $i$ 页压缩后视觉 token 数为 $s_i$，批内方差 $\\mathrm{Var}(s)$ 越大，按均值预算组批就越容易在个别长页上击穿显存；KV cache 峰值近似正比于 $\\sum_i s_i$ 加文本历史，回退样本还会额外驻留显式检测的中间激活。工程上应改用高分位预算而非均值预算组批，并对回退样本单独成批，避免一条串行检测路径拖慢整批解码。尾延迟的主要来源正是回退路径：回退率是尾延迟的一阶预测器，P99 应同时按“隐式路径”和“含回退路径”两条曲线分别统计，否则混合后的均值会掩盖长尾。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要怀疑</th><th>定位手段</th><th>处置</th></tr></thead><tbody><tr><td>顺序错乱、指标缓降</td><td>压缩过度或网格过粗</td><td>置信度分布与压缩比联动曲线</td><td>降压缩比、提高输入分辨率</td></tr><tr><td>批内 OOM 抖动</td><td>按均值预算组批</td><td>批内 $s_i$ 方差与显存峰值</td><td>高分位预算、回退样本隔离成批</td></tr><tr><td>P99 尾延迟抬升</td><td>回退率上升</td><td>分路径统计 P99</td><td>调阈值或扩容显式路径</td></tr></tbody></table>\n<p>回滚必须按“信号层—压缩层—调度层”分级，而非整链路回退到显式检测：先冻结压缩比与回退阈值，再回滚版面偏置注入位置，最后才切回显式版面分析路径。细粒度表格与公式混排是精度侧的主要机制性风险，token 级表达力受网格粒度限制，这类样本应在离线集上单独切片监控，而不是混入总体均值。另一个易被忽视的失败模式是把 token 级版面信号当检测框使用——一旦下游后处理按框裁剪，就丢掉了并行注入的延迟优势并引入额外串行开销。判断准则很直接：若回退率与批内方差同时上行而压缩比未变，问题在网格粒度；若压缩比先行上调，则是调度层为吞吐牺牲了表达力。</p>\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-42\">四十二 · 口径先于数字：这份材料能报什么、不能报什么</h3>\n<p>读 LayoutLite 这类论文的基准章节，第一件事不是找表，而是确认口径边界。给定材料明确写着：数据集名称、基线系统、可核验的数值结果、硬件档位、并行拓扑、量化方案、消融数据均未给出。这意味着任何“端到端精度提升 X%”“吞吐翻倍”“TTFT 降低多少毫秒”的表述都不成立，写进容量规划就是凭空造数。可核验的只有机制层面的变化：版面分析由显式像素级检测转为 token 级隐式信号，推理链路少了一次区域裁剪与二次视觉编码，视觉 token 压缩合并缩短了送入解码器的序列长度。因此本部分的“基准”不是复述别人的跑分，而是给出一套在缺数条件下仍然可执行的测量框架——把哪些量必须自己测、哪些对比天然不可比、哪些指标必须成对报告讲清楚。</p>\n<p>工程上常见的错误是把机制收益直接折算成系统收益。省掉一次区域裁剪确实减少了显存与延迟开销，但减少多少取决于页数、网格分辨率、压缩比与批内序列长度方差，这四个量在材料里全是空白。正确做法是把机制变化翻译成可测的中间量：视觉编码前向次数（从每区域一次降为每页一次）、送入解码器的视觉 token 数（压缩前后）、KV cache 中视觉部分占比、回退率。这些量不依赖论文数字，部署方自己就能在 Blackwell 档位上采到，再据此推算端到端指标。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-43\">四十三 · 硬件档位与 batch 口径：组批单位不是请求数而是 token 预算</h3>\n<p>LayoutLite 的批调度按页数与视觉 token 预算组批，压缩后的序列长度决定单批可容纳页数。这与常规 LLM 服务按请求数或按 token 数组批的口径不同：一个 batch 里装的是若干整页文档，每页贡献固定网格数的视觉 token，经压缩合并后长度不等。于是 batch size 这个字段本身失去可比性——同样是 batch=8，一页 A4 单栏与一页三栏表格混排的 token 预算差出一个量级。跨系统对比时必须同时报出“页数 / 压缩后视觉 token 数 / 文本生成长度分布”三元组，否则吞吐数字无意义。</p>\n<div class=\"formula\">$$B_{\\max}=\\left\\lfloor\\frac{C_{\\mathrm{tok}}-N_{\\mathrm{txt}}}{N_{\\mathrm{vis}}^{\\mathrm{comp}}}\\right\\rfloor,\\quad N_{\\mathrm{vis}}^{\\mathrm{comp}}=\\rho\\,N_{\\mathrm{grid}}$$</div>\n<p>其中 $C_{\\mathrm{tok}}$ 是单批 token 容量上限，$N_{\\mathrm{txt}}$ 为预留的文本历史预算，$N_{\\mathrm{grid}}$ 是整页网格 token 数，$\\rho$ 为压缩合并后的保留比例。这个式子给出两个直接判断：压缩比 $\\rho$ 下降会线性抬高可容纳页数，但压缩过度会削弱细粒度版面表达，精度侧风险与吞吐收益必须联合评估；文本历史预算 $N_{\\mathrm{txt}}$ 在多页长文档场景下会挤压视觉预算，批内页数随生成进度动态收缩，调度器需要支持运行中缩批而非固定 batch。</p>\n<p>硬件档位方面，材料未给出任何 GPU 型号与卡数，因此不能声称“在 B200 上达到某吞吐”。可执行的判断是：视觉编码器与自回归解码器可分离部署以隔离延迟，前者是整页单次前向、计算密集且批内长度整齐，后者是自回归、KV cache 随生成增长、批内长度发散。在 GB200 NVL72 这类机架内，把两段放在不同卡组并用 NVLink 5 传压缩后视觉 token，比混布在同一组卡上更容易做 SLO 隔离；代价是跨卡传输压缩视觉 token 的带宽开销，需与视觉编码的重复计算开销做权衡。量化方案同样空白，NVFP4/FP8 对视觉编码器与跨模态注意力的数值影响无法定量评估，部署前必须自行校准，尤其要盯住版面头置信度分布在低精度下的漂移——置信度阈值是回退路径的触发器，数值噪声会直接改变回退率。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-44\">四十四 · 指标成对报告：TTFT 与 TPOT 不能各自单独出现</h3>\n<p>文档 OCR 的 SLO 关注首 token 延迟与整页生成时延。LayoutLite 把延迟主要落在视觉编码与自回归解码两段，串行检测段被移除，因此 TTFT 的构成变了：不再是“检测模型前向 + 裁剪 + 识别首 token”，而是“整页视觉编码 + 压缩合并 + 解码首 token”。报告 TTFT 时必须注明是否含视觉编码，否则与显式流水线系统的对比会把对方的检测延迟算进 TTFT、把自己的编码延迟漏掉，形成虚假优势。</p>\n<p>TPOT 的口径更微妙。跨模态注意力直接读取全页压缩 token，解码每一步的注意力开销与压缩后视觉序列长度成正比，而非与检测框数量成正比。多栏文档在显式方案里每区域独立解码、序列短；隐式方案里全页 token 参与每一步注意力，单步开销更高但省掉了跨区域的重复编码。因此 TPOT 的对比必须绑定“每页总生成 token 数”与“压缩比”，只报单步毫秒数会掩盖总时延的真实差异。吞吐指标同理：应报“页/秒”而非“token/秒”，因为文档 OCR 的业务单位是页，token 数随版面文字密度剧烈波动。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>必须绑定的口径</th><th>不可比情形</th></tr></thead><tbody><tr><td>TTFT</td><td>是否含整页视觉编码与压缩合并</td><td>一方含检测、一方不含</td></tr><tr><td>TPOT</td><td>压缩后视觉 token 数、每页生成 token 数</td><td>单栏短页 vs 多栏长页混报</td></tr><tr><td>吞吐</td><td>页/秒、批内页数、压缩比</td><td>按请求数报 batch size</td></tr><tr><td>显存</td><td>KV cache 视觉部分占比、峰值含回退路径</td><td>只报稳态不含峰值</td></tr><tr><td>功耗</td><td>整页编码段与解码段分别计量</td><td>混布同卡无法拆分</td></tr></tbody></table>\n<p>显存与功耗两项最容易被漏报。显存峰值必须包含回退路径：版面头置信度低于阈值或输出顺序冲突时，样本回退到显式版面分析，此时检测模型与裁剪缓冲同时驻留，峰值高于稳态。高回退率下批调度会被串行检测拖慢，尾延迟与显存峰值一起恶化，因此回退率应作为一等指标与吞吐并列报告。功耗方面，整页单次编码把计算集中到一段短时高占用区间，与显式方案的多次小批量裁剪编码在功耗曲线上形态不同；若两段混布同卡则无法拆分计量，这也是分离部署的一个附带理由。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-45\">四十五 · 哪些提升不可比：四类典型错配</h3>\n<p>第一类是基线错配。材料未给出基线系统，若拿 LayoutLite 与“检测+裁剪+识别”的串行流水线比，必须确认对方是否也做了视觉 token 压缩、是否也共享视觉编码。若对方每区域重复编码，则差距里混入了重复编码的消除，不能全部归因于隐式版面信号。第二类是负载错配：单栏纯文本页在隐式方案下几乎无收益，因为阅读顺序本就线性；收益集中在多栏、表格、公式混排页，这类页在显式方案里框误差传播最严重。用平均页混合负载报单一数字，会同时低估高复杂度页的收益与低复杂度页的回退风险。</p>\n<p>第三类是精度口径错配。隐式版面信号受视觉 token 网格粒度限制，细粒度表格与公式混排可能超出 token 级表达力，这是精度侧的主要机制性风险。若对比系统在高分辨率网格下运行而 LayoutLite 用低分辨率网格，精度差异里混入了分辨率变量而非版面机制本身。第四类是调度错配：按页数与 token 预算组批的系统，其吞吐随批内序列长度方差变化；若对比方按请求数组批且不做预算对齐，则吞吐差异部分来自调度策略而非模型结构。工程判断是：任何跨系统数字，先问“批内序列长度方差是否对齐、回退率是否披露、视觉编码次数是否一致”，三问有一问不满足，该数字就只能作定性参考。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-46\">四十六 · 自己动手的测量清单：从机制量推到端到端</h3>\n<p>在缺数条件下，可执行的测量顺序是先采机制量、再推系统量。机制量四项：视觉编码前向次数（应为每页一次，若监控到多次说明回退或分块逻辑被触发）、压缩前后视觉 token 数之比 $\\rho$、版面头置信度分布（决定回退阈值位置）、批内序列长度方差（决定调度对齐成本）。系统量三项：含编码的 TTFT、按页计的吞吐、含回退路径的显存峰值。两组量之间的关系可用下式做一阶估算：</p>\n<div class=\"formula\">$$T_{\\mathrm{page}}\\approx T_{\\mathrm{enc}}(N_{\\mathrm{grid}})+T_{\\mathrm{comp}}(N_{\\mathrm{grid}},\\rho)+\\frac{N_{\\mathrm{out}}}{\\mathrm{TPOT}(\\rho N_{\\mathrm{grid}})}+\\eta\\,T_{\\mathrm{fb}}$$</div>\n<p>其中 $\\eta$ 为回退率，$T_{\\mathrm{fb}}$ 为单次回退引入的显式检测延迟。这个式子的工程价值在于暴露尾延迟结构：即使 $\\eta$ 很小，$T_{\\mathrm{fb}}$ 远大于常规解码步，尾延迟仍会被回退样本主导。因此监控项必须包含回退率的时间序列而非仅均值，并按版面头置信度分流——低置信度样本单独成批走显式路径，避免拖慢高置信度批。压缩比 $\\rho$ 的调参也应与精度联合：压缩过度会削弱细粒度版面表达并影响 OCR 精度，而 $\\rho$ 的收益只体现在 $T_{\\mathrm{comp}}$ 与 TPOT 两项上，属于典型的“吞吐换精度”旋钮，必须成对报告。</p>\n<p>最后一条工程判断落在可比性的底线：LayoutLite 的基准叙述只能支撑机制层面的因果链——单次整页编码省去重复视觉编码、压缩合并降低 KV cache 视觉占用、注意力偏置让阅读顺序隐式给出而省去显式排序模块。任何超出这条链的数值主张，都需要部署方在自选的 Blackwell 档位、自选的量化方案、自选的批预算下重新测量，并把回退率、压缩比、批内长度方差三个协变量一并披露，否则数字之间不可比。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-47\">四十七 · 口径边界：回退率、网格粒度与不可比的“提速”</h3>\n<p>读 LayoutLite 的任何端到端数字前，先把口径拆成三层：链路层（是否仍含显式检测）、批层（页数与视觉 token 预算如何对齐）、精度层（压缩比与量化档位）。材料未给出数据集、基线、硬件档位与数值结果，因此可核验的只有机制层面的变化——版面分析由串行检测变为 token 级并行信号，推理链路少一次区域裁剪与二次视觉编码。凡是把这一机制差异直接折算成“端到端加速 N 倍”的表述都不可比：它既未扣除回退路径的串行开销，也未说明视觉编码器与解码器是否同卡、是否同精度档。部署时应把 TTFT 拆为视觉编码段与首 token 解码段，把 TPOT 与压缩后视觉 token 数、文本历史长度绑定报告，否则不同压缩比下的吞吐数字彼此不可读。</p>\n<p>回退路径是口径里最容易被藏起来的一项。版面头置信度低于阈值或输出顺序冲突时，样本转回显式版面分析，等于在原本单次前向的链路上重新插入检测模型与区域裁剪。设回退率为 <span>r</span>，单页隐式路径时延为 <span>T<sub>i</sub></span>、显式路径为 <span>T<sub>e</sub></span>，则批内期望时延与尾延迟近似为：</p>\n<div class=\"formula\">$$E[T]=(1-r)\\,T_{i}+r\\,(T_{i}+T_{e}),\\qquad \\mathrm{P99}\\ \\text{由}\\ r\\ \\text{与批内最大页数共同决定}$$</div>\n<p>显存峰值同理：回退样本会同时驻留压缩视觉 token 与检测阶段的中间特征，高回退率下批调度被迫缩小页数预算，吞吐随之下滑。因此报告吞吐必须同时给出回退率与批内序列长度方差，否则“压缩后单批页数提升”只是账面数字。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>可比条件</th><th>不可比情形</th></tr></thead><tbody><tr><td>TTFT</td><td>同页数、同视觉 token 预算、同精度档</td><td>一方含检测前置段，另一方不含</td></tr><tr><td>吞吐</td><td>同回退率区间、同批内长度方差</td><td>高回退率批次与低回退率批次混报</td></tr><tr><td>显存</td><td>同压缩比、同 KV cache 精度</td><td>压缩比不同却直接比峰值</td></tr><tr><td>精度</td><td>同网格粒度、同回退阈值</td><td>细粒度表格/公式样本占比不同</td></tr></tbody></table>\n<p>精度侧的主要机制性风险在网格粒度：隐式版面信号由视觉 token 网格承载，细粒度表格与公式混排可能超出 token 级表达力，此时提高压缩比会进一步削弱顺序信号，表现为阅读顺序冲突而非字符错误，恰好触发回退。工程判断是：把压缩比、回退阈值与网格分辨率作为一组联合校准参数，在目标文档分布上先测回退率与顺序冲突率，再决定吞吐口径；NVFP4/FP8 对视觉编码器与跨模态注意力的数值影响材料未给出，部署前须自行校准，不能把量化带来的吞吐增益与版面机制增益混在同一张对比表里。</p>\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-48\">四十八 · 迁移到非文档视觉模型：改的是注入位置，不是压缩模块</h3>\n<p>LayoutLite 的可迁移部分不是“版面”这个概念，而是“在视觉 token 序列上预测一个序列级偏置，并以注意力偏置形式注入跨模态注意力”这条通路。迁到通用 VLM（图文问答、图表理解、UI 截图理解）时，要改的第一件事是版面头的标签体系：文档 OCR 的标签是版面角色与阅读顺序，而 UI 截图需要的是控件层级与可交互区域，图表需要的是坐标轴—图例—数据系列的归属关系。标签体系一变，<span class=\"formula\">$$b^{\\mathrm{layout}}$$</span> 的语义就从“阅读顺序先验”变成“结构归属先验”，注入位置也要跟着变——文档 OCR 适合注入到跨模态注意力的 key 侧（约束解码器读哪些 token、按什么顺序读），而 UI 理解更适合注入 query 侧（约束当前生成位置应关注哪一层控件）。</p>\n<p>代价判断很直接：注入位置改到 query 侧后，偏置矩阵不再能按序列一次性预计算并复用，每个解码步都要重算，跨模态注意力的算力开销上升；而注入 key 侧时偏置可在编码后固化，解码步只做查表。因此在 Blackwell 上做迁移评估时，先问一句“偏置能否在编码阶段固化”，能固化就保留 LayoutLite 的低延迟形态，不能固化就要按解码步数乘算力预算。压缩合并模块反而是最不需要改的部分——它只依赖 token 相似度，与标签语义无关，迁到任何视觉编码器输出上都能直接复用，但压缩比例必须重标定：文档页面的冗余主要来自空白区，UI 截图的冗余来自大面积同色背景，图表则几乎没有可合并的冗余 token，沿用文档场景的压缩比会把坐标轴刻度 token 合掉。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-49\">四十九 · 迁到非 OCR 任务：解码器侧假设最先失效</h3>\n<p>LayoutLite 的推理链路隐含一个假设：输出是长文本序列，自回归解码占主导，视觉编码只做一次，因此“省掉一次区域裁剪与二次编码”的收益主要体现在首 token 延迟和显存峰值上。迁到短输出任务（分类、检索、单句描述）时，这个假设翻转：解码只走几步，视觉编码成为端到端延迟的主体，此时省掉检测模块的收益从“解码段”转移到“编码段”，收益依然存在但量级变小；而版面头本身在编码后要多跑一次序列级前向，对短输出任务反而是纯开销。</p>\n<p>判断标准可以写成一条粗算：设视觉编码延迟为 <span class=\"formula\">$$T_{\\mathrm{enc}}$$</span>，解码步数为 <span class=\"formula\">$$N$$</span>，单步解码延迟为 <span class=\"formula\">$$t_{\\mathrm{dec}}$$</span>，显式方案额外检测延迟为 <span class=\"formula\">$$T_{\\mathrm{det}}$$</span>，则隐式方案的净收益近似为 <span class=\"formula\">$$G \\approx T_{\\mathrm{det}} - T_{\\mathrm{head}}$$</span>，与 <span class=\"formula\">$$N$$</span> 无关；显式方案的收益则随 <span class=\"formula\">$$N$$</span> 增大而放大，因为省掉的二次编码会在每个需要回看的区域上重复计费。结论是：<span class=\"formula\">$$N$$</span> 小的任务上 LayoutLite 的迁移价值主要落在显存与批调度，而非延迟；<span class=\"formula\">$$N$$</span> 大的任务（长文档转写、表格逐行生成）才是它延迟优势的主场。这也解释了为什么把它迁到 VQA 类短输出任务时，工程上更该保留显式检测做兜底而不是全面替换。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-50\">五十 · 规模上限：网格粒度与回退率共同封顶</h3>\n<p>规模上限不在参数量，而在两个可测量量：视觉 token 网格粒度与回退率。网格粒度决定了版面信号的分辨率上限——一个 token 覆盖的图像区域越大，落在同一 token 内的不同版面角色就越难区分。设页面被切成 <span class=\"formula\">$$G_h \\times G_w$$</span> 的网格，单个 token 覆盖面积约为 <span class=\"formula\">$$\\frac{HW}{G_h G_w}$$</span>，当表格单元格或公式上下标的物理尺寸小于该面积时，token 级表达力就到顶了，再增大模型也不会恢复这部分信息。这是机制性上限，不是调参能绕过的。</p>\n<p>第二个上限来自回退率。回退路径一旦触发，样本要重新走显式检测加区域裁剪，等于把省掉的串行段又加回来，并且是在批已经组好之后加回来——批内其他样本的解码被拖住，尾延迟抬升，显存峰值因为同时持有隐式路径的全页 token 与显式路径的裁剪特征而抬升。设回退率为 <span class=\"formula\">$$r$$</span>，则有效端到端延迟近似为 <span class=\"formula\">$$T_{\\mathrm{e2e}} \\approx (1-r)\\,T_{\\mathrm{implicit}} + r\\,(T_{\\mathrm{implicit}} + T_{\\mathrm{det}} + T_{\\mathrm{crop}})$$</span>，线性项 <span class=\"formula\">$$r\\,(T_{\\mathrm{det}}+T_{\\mathrm{crop}})$$</span> 就是规模上限的直接来源。工程判断：当 <span class=\"formula\">$$r$$</span> 超过某个自校准阈值（按 SLO 尾延迟倒推，而不是拍脑袋定），这套方案在容量规划上就不该按隐式路径的单页成本来算，而要按混合路径算，单机可承载页数随之下降。监控项里版面头置信度分布与回退率必须与压缩比、批内序列长度方差并列上报，否则容量模型会系统性低估。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-51\">五十一 · 数值精度迁移：NVFP4/FP8 下先校准偏置，再校准压缩</h3>\n<p>材料未给出量化方案，因此迁移到 Blackwell 的 NVFP4/FP8 时必须自行校准，且校准顺序有讲究。版面偏置 <span class=\"formula\">$$b^{\\mathrm{layout}}$$</span> 是加在 softmax 之前的 logit 项，量级通常远小于 <span class=\"formula\">$$qk^{\\top}/\\sqrt{d}$$</span>；若把偏置与注意力 logit 一起做低精度量化，偏置的有效位会被主项吃掉，版面信号在数值上退化成一个近似常数，等于隐式版面分析失效但系统不会报错。正确做法是把偏置作为独立的高精度旁路（FP16 或 BF16 累加），只对 <span class=\"formula\">$$qk^{\\top}$$</span> 走 FP8/NVFP4，这样跨模态注意力的算力收益保留，版面信号的数值保真也保留。</p>\n<p>压缩合并模块的量化风险在另一侧：相似度合并依赖 token 向量的相对距离，低精度量化会压缩距离分布的动态范围，使本应合并的冗余 token 因距离被量化到同一桶而误合，或本应保留的细粒度 token 因距离被拉平而误合。代价是精度侧不可见的缓慢退化，只在表格与公式混排页面上体现为字符错位。工程判断：压缩比例与量化精度必须联合评估，先固定压缩比校准量化，再固定量化回看压缩比，两次都过再上线；只调其中一个会把另一个的退化误判为模型能力问题。功耗侧，视觉编码器单次整页前向是功耗主项，隐式方案省掉的二次编码直接省掉这部分重复功耗，但版面头与压缩模块的额外前向会部分抵消，净功耗收益取决于压缩比——压缩比越高，解码段 KV cache 读取带宽越低，功耗收益越明显。</p>\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-52\">五十二 · 不适用边界：三类场景应直接放弃迁移</h3>\n<p>第一类是高精度版面约束场景，例如票据字段抽取、证照识别。这类场景的输出顺序与字段归属有强合规要求，隐式顺序信号不可解释、不可审计，回退率再低也不能作为主路径，因为一旦出错无法定位是版面头还是解码器的问题。第二类是版面密度超过网格表达力的场景，细粒度表格与公式混排已在材料中确认为机制性风险，迁移时应先做网格粒度与目标元素尺寸的比对，元素尺寸小于单 token 覆盖面积就直接判不适用，不要指望靠增大视觉编码器分辨率硬扛——分辨率上升会推高编码延迟与显存，而 token 压缩又会把刚买来的分辨率合掉，形成负向循环。第三类是流式或分块输入场景，LayoutLite 的整页单次前向假设与流式输入冲突，跨页版面连续性无法在单次前向内建立，硬迁会把跨页表格拆断。</p>\n<p>反过来，明确适用的迁移方向是：输出为长文本、版面结构以阅读顺序为主、允许少量回退且回退可被批调度隔离的文档类任务。迁移时的最小改动集是重标定压缩比、把偏置改为高精度旁路、按回退率重算容量模型，三项都不涉及模型结构改动，这也是这套方案在工程上真正的可迁移性所在——它迁移的是推理链路的组织方式，而不是某个检测头的权重。</p>\n\n\n<h3 id=\"paper-layoutlite-token-level-implicit-layo-2026-sec-53\">五十三 · 迁移与边界：换模型、换领域、上规模时真正要动的地方</h3>\n<p>把 LayoutLite 的推理链路迁到另一个多模态模型，改动量集中在三处接口而非模型本体：视觉编码器的 token 网格定义、版面头的输出语义、跨模态注意力的偏置注入点。网格定义决定 token 与页面坐标的对应关系，换编码器（不同 patch 尺寸、不同分辨率策略）就必须重算网格到阅读顺序的映射，否则 <span class=\"formula\">$$b^{\\mathrm{layout}}$$</span> 注入的偏置与实际版面位置错位，解码器读到的顺序信号变成噪声。版面头输出的是角色类别与顺序偏置，迁到新模型时若解码器层数或注意力头结构变化，偏置需按头维度广播或改为逐层独立预测，这是一次真实的工程改造而非配置项。注入点若从跨模态注意力移到自注意力，版面信号会污染文本历史的建模，必须保留在跨模态分支上。代价上，这三处改造不影响视觉编码的显存峰值，但会改变解码阶段的注意力计算图，偏置张量的形状随头数与层数线性增长，在长页、多头配置下这部分显存不可忽略。</p>\n<p>领域迁移的失效条件很明确：token 级隐式信号表达力受网格粒度约束。整页扫描件、单栏报告、常规多栏论文在中等网格下顺序信号足够；细粒度表格（单元格级对齐）、公式与正文混排、脚注与边栏交错时，单个 token 覆盖的像素区域跨越多个语义单元，版面头无法在 token 维度上区分“同一单元格内的换行”与“跨栏跳转”，阅读顺序冲突概率上升，回退率随之升高。回退路径不是免费的兜底：它重新引入显式检测模型与区域裁剪，等于把被省掉的串行前置模块加回链路，尾延迟与显存峰值同时抬升。设回退率为 <span class=\"formula\">$$r$$</span>，单页基线延迟为 <span class=\"formula\">$$T_{\\mathrm{fast}}$$</span>，回退路径延迟为 <span class=\"formula\">$$T_{\\mathrm{fb}}$$</span>，则有效延迟 <span class=\"formula\">$$T_{\\mathrm{eff}}=(1-r)T_{\\mathrm{fast}}+r\\,T_{\\mathrm{fb}}$$</span>，由于 <span class=\"formula\">$$T_{\\mathrm{fb}}$$</span> 含检测与二次编码，即使 <span class=\"formula\">$$r$$</span> 不高，尾延迟也会被显著拉长；批调度中若回退样本与快速样本混批，整批被串行检测拖慢，这是部署监控必须盯住的指标。</p>\n<p>规模上限来自两个方向。其一是批内序列长度方差：调度按页数与视觉 token 预算组批，压缩合并后的序列长度决定单批页数，但版面复杂度差异使同一预算下不同页的实际 token 数离散，方差大时批的有效利用率下降，吞吐被最长的样本钳制。其二是压缩比例与精度的耦合：压缩合并按相似度合并冗余 token，压缩越激进 KV cache 中视觉部分越小、单批可容纳页数越多，但细粒度版面表达同步削弱，OCR 精度在表格与公式区域先退化。迁移到 Blackwell 部署时，材料未给出量化方案与硬件档位，NVFP4/FP8 对视觉编码器与跨模态注意力的数值影响无法定量评估，部署前须自行校准压缩比例与 KV cache 精度的联合配置，并把版面头置信度分布、回退率、压缩比、批内序列长度方差列为常驻监控项。</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>必须改动</th><th>不适用/失效信号</th></tr></thead><tbody><tr><td>换视觉编码器</td><td>重算网格到顺序映射、偏置形状</td><td>网格粒度跨语义单元</td></tr><tr><td>换解码器结构</td><td>偏置按头/层广播，保留跨模态分支</td><td>偏置误注入自注意力</td></tr><tr><td>换文档领域</td><td>回退阈值与分流策略</td><td>表格/公式混排回退率升高</td></tr><tr><td>上规模批调度</td><td>按 token 预算对齐、方差监控</td><td>混批被串行检测拖慢</td></tr></tbody></table>\n<p>判断落在具体机制上：这套方案适合“整页一次编码、版面中等复杂度、回退可分流”的服务形态；若业务以单元格级表格抽取为主，或要求确定性阅读顺序，token 级隐式信号不足以替代显式检测，应保留显式路径作为主链路而非兜底。迁移时先固定注入点与偏置形状，再调压缩比例，最后用回退率与批内方差两个指标决定是否扩大批预算。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">LayoutLite: Token-Level </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Implicit Layout…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2026 · arXiv preprint</text></svg><figcaption><b>家谱</b> · LayoutLite: Token-Level… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出基线系统</td></tr><tr><td>主要结果</td><td>材料未给出可核验的数值结果，无法报告端到端精度、吞吐或延迟对比；论文卡仅记…</td></tr><tr><td>消融</td><td>材料未给出消融实验数据；从机制看，可消融项应包括版面头损失权重、注意力偏置…</td></tr><tr><td>局限</td><td>材料未给出评测边界与失败样本分布；可确认的机制性限制是隐式版面信号依赖视觉…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-layoutlite-token-level-implicit-layo-2026 · 共 9 个片段</p>\n";break;}}})();
